  }
  button {
    background: none;
    border: none;
    padding: 0;
    font: inherit;
    color: inherit;
    cursor: pointer;
  }
  button:disabled {
    cursor: default;
  }
  * {
    scrollbar-width: none;
  }
  ::-webkit-scrollbar {
    display: none;
  }
}
