/*
 * Trilorah design tokens — extracted from Figma, Section 1 (38:236).
 *
 * The system is one gradient whose ALPHA carries state. Every surface in
 * the design shares the same four colour stops at the same four positions;
 * rest sits at 0.30 and hover/active at 0.65–0.70. Nothing else changes.
 * That is why these are variables and not forty hand-written gradients.
 */

:root {
  /* ---------------------------------------------------------------- */
  /* Gradient stops — identical everywhere, only the hue set swaps     */
  /* ---------------------------------------------------------------- */
  --tri-teal-1: 7 21 26; /* #07271C */
  --tri-teal-2: 24 70 55; /* #1D322F */
  --tri-teal-3: 18 34 37; /* #1A3630 */
  --tri-teal-4: 44 55 71; /* #1A3336 */

  /*
   * Further hue sets. Each is the teal ramp with its hue turned: the same
   * lightness at each stop (dark, then three near-equal steps) and the same
   * faint drift across the last three, which is what keeps the surface from
   * looking like flat tint. Because a tone is only these four numbers, every
   * one of them inherits the two-phase hover — middle first, edges trailing —
   * without a line of its own.
   */

  /* Ash — the neutral. For any control that should not claim to be about
     anything: it is the teal ramp with the colour taken out and a trace of
     cool left so it does not go dead grey against warm content. */
  --tri-ash-1: 22 24 26; /* #16181A */
  --tri-ash-2: 40 43 45; /* #282B2D */
  --tri-ash-3: 43 45 47; /* #2B2D2F */
  --tri-ash-4: 40 44 48; /* #282C30 */

  /* Gold — the same family as --tri-accent-yellow, taken down to a surface.
     For "now", "live", anything the eye should reach first. */
  --tri-gold-1: 42 33 9; /* #2A2109 */
  --tri-gold-2: 56 51 28; /* #38331C */
  --tri-gold-3: 59 53 27; /* #3B351B */
  --tri-gold-4: 58 48 26; /* #3A301A */

  /* Indigo — cool and quiet, for a second voice that is not a warning. */
  --tri-indigo-1: 12 7 39; /* #0C0727 */
  --tri-indigo-2: 29 29 52; /* #1D1D34 */
  --tri-indigo-3: 31 26 55; /* #1F1A37 */
  --tri-indigo-4: 38 26 55; /* #261A37 */

  /*
   * Go and caution — the two BRIGHT tones, and the only ones.
   *
   * Every ramp above is a dark surface that light ink sits on, and alpha
   * carries its state. These two invert that: the surface is the ink colour
   * itself (the mint of --tri-go-2 is the app's own mint, the gold is
   * --tri-accent-yellow) and the label goes dark. They exist for the one or
   * two acts on a screen that reach the congregation — "go live", and the
   * reset that undoes it — which have to be findable in a glance across a
   * booth, and a 30%-alpha teal among 30%-alpha ash is not. Same four-stop
   * recipe, same angle, same drift across the last three stops, so they are
   * still the system's surface rather than a second kind of button.
   */
  --tri-go-1: 72 178 152; /* #48B298 */
  --tri-go-2: 143 211 192; /* #8FD3C0 */
  --tri-go-3: 156 222 201; /* #9CDEC9 */
  --tri-go-4: 104 196 168; /* #68C4A8 */

  --tri-caution-1: 201 178 78; /* #C9B24E */
  --tri-caution-2: 228 216 122; /* #E4D87A */
  --tri-caution-3: 236 225 142; /* #ECE18E */
  --tri-caution-4: 212 192 96; /* #D4C060 */

  /* What is written on a bright surface: the teal ramp's own dark, so the
     label is still the system's colour and not a neutral black. */
  --tri-ink-on-bright: #06201a;

  --tri-red-1: 92 16 16; /* #5C1010 */
  --tri-red-2: 118 26 26; /* #761A1A */
  --tri-red-3: 120 34 34; /* #782222 */
  --tri-red-4: 75 18 18; /* #4B1212 */

  /*
   * Figma has a different angle on every component (49.5°, 47.8°, 42.6°,
   * 54.6°, 33.4°, 28.1°) with identical stops — that is resize drift, not
   * intent. Normalised to two: one for controls, a flatter one for wide
   * surfaces where a steep angle would band.
   */
  --tri-angle: 48deg;
  --tri-angle-wide: 33deg;

  /* Alpha = state. The whole interaction model. */
  --tri-alpha-rest: 0.3;
  --tri-alpha-hover: 0.7;
  --tri-alpha-active: 0.65;

  /* ---------------------------------------------------------------- */
  /* Ink                                                              */
  /* ---------------------------------------------------------------- */
  --tri-ink: #e5f3f2;
  --tri-ink-muted: rgb(229 243 242 / 0.64);
  --tri-stroke-opacity: 0.12;
  --tri-stroke-opacity-hover: 0.04;
  --tri-ink-faint: rgb(229 243 242 / var(--tri-stroke-opacity)); /* control borders */
  --tri-edge: rgb(var(--tri-teal-4) / 0.48); /* follows the selected colour theme */

  --tri-ink-danger: #eac7c6;
  --tri-ink-danger-hover: #fec9c9;
  --tri-accent-yellow: #e4d87a;

  /* A lifted surface — the body of anything that opens over the screen (an
     expanded tile, the song editor, a dialog) — and the ground it dims. One
     pair, so every popup is the same material at the same depth. */
  --tri-pop: rgb(20 20 22);
  --tri-pop-scrim: rgb(0 0 0 / 0.55);

  --tri-text-shadow: 0 1px 3.2px rgb(0 0 0 / 0.48);

  /* ---------------------------------------------------------------- */
  /* Shape & type                                                     */
  /* ---------------------------------------------------------------- */
  /* Back near the file's 6/8 (owner, 2026-10-08: "way less rounded,
     everything"). These had been raised to 18/30, which made every button
     a stadium and every card a pillow. The px radii hard-coded around the
     app were cut in the same pass, and Tailwind's rounded-md…3xl scale is
     cut in index.css. */
  --tri-radius-control: 6px;
  --tri-radius-surface: 10px;

  /*
   * Figma runs corner smoothing at 100% (iOS) on top of the 6px radius, so
   * the corners are superellipses, not circular arcs. Chromium 142 — the
   * only engine we ever run on — ships `corner-shape`, so there is no
   * fallback path to maintain.
   *
   * `squircle` is superellipse(2) — the full-smoothing curve. At the small
   * radii Figma drew (6/8px) that is imperceptible, but at the radii above
   * it over-flattens the corner's midpoint and the box starts to read as a
   * lozenge rather than a rounded rect. Apple's own continuous corner sits
   * short of that: the curve carries further round the turn and meets the
   * side with less of a straight run into it. superellipse(1.6) is that
   * shape — still unmistakably smoothed, but the corner reads as a corner
   * at 30px the way squircle only does at 8px.
   */
  --tri-corner: superellipse(1.6);

  /*
   * Control metrics. Figma's 9px/28px reads cramped at real size, so the
   * button is one step up from the file — the radius and smoothing are
   * unchanged, only the box around them.
   */
  /*
   * Every outline in the app, one number. Rings used to be drawn by hand at
   * 1px, 1.45px (the Figma inspect value) and 1.7px depending on who wrote
   * the component, which read as three different strokes sitting next to
   * each other on the same screen. Anything that draws a box outline now
   * references this; only the colour and opacity are the caller's.
   *
   * Rules and dividers — `inset 0 -1px 0`, table border-t — are NOT this.
   * A line between two things is not an outline around one.
   */
  --tri-border: 1.2px;

  /* ---------------------------------------------------------------- */
  /* Tier-scaled metrics — see F-05 at the foot of this file           */
  /* ---------------------------------------------------------------- */
  /*
   * Every intrinsic size in the system lives here and nowhere else. A
   * component that hard-codes its own height cannot be reached by a tier,
   * and with ~181 components to build, "reached by one rule" is the only
   * version of this that works. If you find yourself typing a pixel height
   * into a primitive, it belongs in this block instead.
   */
  --tri-control-h: 32px; /* button */
  --tri-control-pad-x: 12px;
  --tri-control-size: 12px;
  --tri-field-h: 38px; /* select trigger */
  /* The top bar row — context bar, panel headers, the rail's mode buttons.
     Its own token because those read as a header strip rather than a field,
     but the presence comes from the rule under them and the type inside, not
     from height: at 44px the strip was a slab with a word floating in it.
     Now one row past the control it holds — a 32px button with 3px to
     breathe — which lands it on the field height, and the whole top of the
     window sits on a single line. */
  --tri-bar-h: 38px;
  /*
   * The topmost strip — the context bar on the right, and the header band of
   * the panel that starts level with it on the left.
   *
   * A token of its own rather than the "+ 8px" that used to be typed at each
   * use. That row holds the view switch, the two pills the operator reaches
   * for most, and wants to be a hand's target rather than a header — but the
   * run-of-service header beside it has to be exactly as tall or the top of
   * the window comes apart into two lines that nearly agree.
   *
   * Written out per tier instead of derived from --tri-bar-h, because the
   * panel header sets --tri-bar-h to THIS to match, and a token defined off
   * the one that points back at it is a cycle CSS throws away.
   */
  --tri-topbar-h: 46px;
  /*
   * The room a bar leaves around the control it holds — half the difference
   * between the two heights, which is the 3px noted above.
   *
   * A token rather than an inline calc because it is also the RIGHT inset of
   * an action button in a panel header: a "+" 3px off the top and bottom but
   * 16px off the right is not centred in anything, it is just near a corner.
   * One value, so the gap around it reads the same on all three sides at
   * every tier.
   */
  --tri-bar-inset: calc((var(--tri-bar-h) - var(--tri-control-h)) / 2);
  /*
   * One row of live transcript, and the strip that has to hold two of them.
   *
   * The context bar used to show the preacher's last sentence on a single
   * line and drop it the instant the next one landed, which is the one thing
   * an operator cannot read fast enough to use. Two lines is what it takes to
   * still have the sentence that set up the one being said now; anything
   * deeper is reading, and reading happens on the dashboard.
   *
   * --tri-topbar-live-h is a max() rather than a flat number so the strip is
   * never SHORTER than the row it replaces: the controls it sits beside are
   * 41/46/53px by density and two lines of transcript are 41/43/47px, so the
   * strip is the height of its buttons at every tier and the transcript
   * centres in it. The max() stays because it is the guarantee, not because
   * the text currently wins — change the leading or the row count and it is
   * what keeps the top of the window from coming apart. The 13px is the
   * pill's own padding, top and bottom together.
   */
  --tri-transcript-leading: 15px;
  --tri-topbar-live-h: max(var(--tri-topbar-h), calc(2 * var(--tri-transcript-leading) + 13px));
  /*
   * The rail's column — the run of service on the left of S-02.
   *
   * A token because the operator posture fills this column and the dashboard
   * leaves it empty, and the two have to agree to the pixel. When the width
   * lived only on the rail, switching to the dashboard took the column out of
   * the row entirely and the whole top strip — the view switch included —
   * slid left by its width and then grew to fill it. The bar is the one thing
   * both postures share, so it is the one thing that must not move when you
   * switch between them. The dashboard now holds the same column open and
   * draws nothing in it. See Live.tsx.
   */
  --tri-rail-w: 20%;
  /* A field on a toolbar, where the control is one of several things sharing
     a row rather than the subject of the panel. Same type, less slab. */
  --tri-field-h-sm: 32px;
  /* Shorter than the select on purpose: a slider is a line you grab, not a
     box you open, and at field height it reads as a slab. */
  --tri-slider-h: 30px;
  --tri-option-h: 33px; /* a row in an open dropdown */
  --tri-row-h: 39px; /* dashboard row */
  --tri-card-w: 108px; /* position card — the floor it will not shrink past */
  /*
   * And the ceiling it will not grow past — 1.5× the tier size. The cards
   * are fluid so they can share a row, but a card is a CONTROL, and controls
   * are sized by the tier, not by the window: on a 2560 display an uncapped
   * position card reached ~280px — two and a half times what was drawn —
   * while its caption stayed 11px, which is how "some things look oversize"
   * happens. Past the cap, extra width becomes space between the cards.
   * Derived, so every tier gets its own ceiling without three more numbers.
   */
  --tri-card-max: calc(var(--tri-card-w) * 1.5);
  /* Its shape, unitless so aspect-ratio can take it. Constant across tiers:
     a card gets bigger between tiers, it does not change proportion. */
  --tri-card-ratio: 108 / 57;
  --tri-card-gap: 5px; /* the concentric inset on both card types */
  /*
   * The bento gap — the space between two surfaces that sit side by side.
   *
   * It was 0.45rem hand-typed in a dozen places across the live surface,
   * which is exactly how a layout ends up with a 7px gutter in one row and
   * an 8px one in the next. One token, so a panel added later cannot invent
   * its own gutter, and so the whole grid can be loosened in one edit.
   *
   * NOT --tri-card-gap: that is the concentric inset INSIDE a surface, the
   * frame between a card's edge and its content. A gap between two boxes and
   * a frame within one box are different jobs and drift apart between tiers.
   */
  --tri-gap: 4px;
  /*
   * Card corners are a PROPORTION of the card, not a pixel size.
   *
   * Both card types size themselves from their container, so a fixed radius
   * drifts badly: the same 22px was 36% of a font card at 1280 and 14% at
   * 2560 — a blob at one end and a near-rectangle at the other. Expressed in
   * cqw (1% of the card's own width) the corner holds its proportion at
   * every size, which is what "the same component" actually means.
   *
   * These were the Figma ratios, 22/86 for the font card and 20/108 for the
   * position card; cut to about a third with the rest of the app's corners
   * (owner, 2026-10-08: "way less rounded").
   */
  --tri-card-round: 5; /* position card, % of its width */
  --tri-font-card-round: 7; /* font card, % of its width */
  --tri-handle-h: 16px;
  --tri-handle-h-active: 23px;

  /* Same face as the rest of the interface; the literal is the fallback for
     any surface that loads tokens.css without index.css. */
  --tri-font: var(--font-ui, 'Geist', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif);
  --tri-font-heading: var(--font-heading, 'Geist', sans-serif);
  /* Up from the file's 12/10. Figma was drawn at screen-reading distance;
     the operator is at arm's length in a dark booth, often standing. */
  /*
   * The type scale, named by the job each step does. Five steps, and nothing
   * outside them — six ad-hoc sizes had accumulated across the screens
   * (9, 10, 11, 12, 13, 14) doing four jobs between them.
   *
   *   eyebrow  uppercase and tracked: column headers, badges, pills
   *   xs       meta: status lines, numeric readouts, hints
   *   body     content rows: a verse, a lyric, a list item
   *   sm       secondary: captions, authorship, sub-labels
   *   (base)   controls and titles — --tri-size
   */
  --tri-size-eyebrow: 10px;
  --tri-size-xs: 10px;
  /*
   * Content, so it does NOT scale with density — see the tier note below. A
   * bigger screen shows more verses, it does not show bigger ones.
   */
  --tri-size-body: 11px;
  --tri-size: 12px;
  --tri-size-sm: 11px;
  /* 1.45, not the old 2.0 — that ratio was set against a 12px label and
     left behind when the type scale went up. */
  --tri-leading: 20px;
  --tri-tracking: 0.01em;
  /* Medium, not regular: at 12–13px over a gradient, regular goes thin. */
  --tri-weight: 500;

  /* ---------------------------------------------------------------- */
  /* Motion                                                           */
  /* ---------------------------------------------------------------- */
  /*
   * Two curves, not ten. The built-in CSS easings are too weak to read as
   * intentional; these are the strong variants. Nothing in this system uses
   * ease-in — it withholds movement at the exact moment the user is looking
   * hardest, which reads as lag.
   */
  --tri-ease-out: cubic-bezier(0.23, 1, 0.32, 1);
  --tri-ease-in-out: cubic-bezier(0.77, 0, 0.175, 1);
  /* Silky, ultra-soft decelerating curve for phase 2 edge bloom */
  --tri-ease-soft: cubic-bezier(0.16, 1, 0.3, 1);

  /* Press feedback has to land inside the same frame the finger does. */
  --tri-dur-press: 140ms;
  --tri-dur-state: 110ms;
  /* The dark edges trail the middle with a soft, gentle feather out. */
  --tri-dur-state-trail: 240ms;
  --tri-delay-trail: 40ms;
  /*
   * A rung of the live-transcript ladder, up or down.
   *
   * Much longer than the 110ms state change, and on purpose: this is not
   * feedback for something the operator did, it is the room talking. Tuned
   * by eye at 1280 against real Deepgram cadence — under about 350ms the
   * ladder flickers between fast sentences, over about 700ms a new line is
   * still arriving when the next one lands and they overlap.
   */
  --tri-dur-transcript: 480ms;
  --tri-press-scale: 0.97;
}

/* ------------------------------------------------------------------ */
/* Corners                                                             */
/* ------------------------------------------------------------------ */

/*
 * Radius and smoothing always travel together — use these instead of a
 * bare `rounded-[var(--tri-radius-*)]`, so no surface can ship a plain
 * circular corner by omission.
 */
.tri-rounded-control {
  border-radius: var(--tri-radius-control);
  corner-shape: var(--tri-corner);
}

.tri-rounded-surface {
  border-radius: var(--tri-radius-surface);
  corner-shape: var(--tri-corner);
}

/*
 * The outline — an inset shadow, not a border, and that is deliberate.
 *
 * A CSS border on a squircle draws its inner edge as a *smaller superellipse*
 * rather than a true constant-width offset of the outer one, so the stroke
 * visibly fattens at each corner. An inset shadow is stroked along the shape
 * itself and stays even the whole way round. (`outline` behaves correctly
 * too, but it is reserved for focus rings.)
 *
 * Colour comes from --tri-stroke-color so a surface can swap the hairline for
 * the solid edge without redeclaring the geometry.
 */
.tri-stroke {
  box-shadow: inset 0 0 0 var(--tri-border) var(--tri-stroke-color, rgb(229 243 242 / var(--tri-stroke-opacity)));
  transition: box-shadow var(--tri-dur-state) var(--tri-ease-out);
}

/* ------------------------------------------------------------------ */
/* The gradient surface                                                */
/* ------------------------------------------------------------------ */

/*
 * Alpha is animated per band rather than as one number, so the surface
 * lights up from the inside out: the center highlight comes up first, then
 * the corner layers and dark outer stop follow. Registering them tells the engine
 * they are numbers, which is what makes them interpolate at all — an
 * unregistered custom property would jump.
 *
 * Both still read from --tri-alpha, so every state (rest, hover, active,
 * solid) sets that one value and gets the staged reveal for free.
 */
@property --tri-a-mid {
  syntax: '<number>';
  inherits: false;
  initial-value: 0.3;
}

@property --tri-a-edge {
  syntax: '<number>';
  inherits: false;
  initial-value: 0.3;
}

.tri-surface {
  --tri-alpha: var(--tri-alpha-rest);
  --tri-a-mid: var(--tri-alpha);
  --tri-a-edge: var(--tri-alpha);
  --tri-1: var(--tri-teal-1);
  --tri-2: var(--tri-teal-2);
  --tri-3: var(--tri-teal-3);
  --tri-4: var(--tri-teal-4);
  background-image:
    radial-gradient(ellipse at 12% 115%, rgb(var(--tri-2) / var(--tri-a-edge)), transparent 62%),
    radial-gradient(ellipse at 88% -25%, rgb(var(--tri-4) / var(--tri-a-edge)), transparent 64%),
    radial-gradient(ellipse at 48% 48%, rgb(var(--tri-3) / var(--tri-a-mid)), rgb(var(--tri-1) / var(--tri-a-edge)) 82%);
  /*
   * Decelerating, and the edges outlast the middle — the light reads as
   * spreading outward rather than as two things switching on. Declared here
   * so every surface inherits the same ramp; components no longer carry a
   * transition utility of their own.
   */
  transition:
    --tri-a-mid var(--tri-dur-state) var(--tri-ease-out),
    --tri-a-edge var(--tri-dur-state-trail) var(--tri-ease-soft) var(--tri-delay-trail),
    color var(--tri-dur-state) var(--tri-ease-out),
    transform var(--tri-dur-press) var(--tri-ease-out);
}

/* Let the center light first, then carry that brightness to the sides. */
button.tri-surface {
  --tri-delay-trail: 80ms;
  --tri-dur-state-trail: 200ms;
}

/*
 * Reduced motion keeps the brightness change — it carries meaning — and
 * drops only the timing that makes it feel like movement.
 */
@media (prefers-reduced-motion: reduce) {
  .tri-surface {
    transition-duration: 1ms;
    transition-delay: 0s;
  }
}

/* ------------------------------------------------------------------ */
/* Live transcript ladder                                              */
/* ------------------------------------------------------------------ */

/*
 * The preacher's speech in the context bar, as a ladder of three lines
 * rather than one line that vanishes.
 *
 * The complaint this answers, in the owner's words: the old strip showed a
 * single sentence and replaced it outright, so the operator never got to
 * finish reading one before it was gone. Three lines, newest at the bottom,
 * and a line does not disappear — it dims one rung.
 *
 * The ladder is expressed as one custom property, --tri-line-a, set per row
 * from the row's distance to the newest. Opacity is animated rather than
 * display or height, because only opacity and transform are free on the
 * compositor and this strip is repainting while the engine transcribes.
 */
.tri-transcript-line {
  opacity: var(--tri-line-a);
  /*
   * The symmetry the owner asked for: an arriving line fades IN over
   * exactly the time every line above it takes to fade DOWN a rung. Same
   * duration, same curve, so the whole ladder moves as one gesture instead
   * of one thing appearing while others blink out.
   */
  transition: opacity var(--tri-dur-transcript) var(--tri-ease-out);
}

/*
 * A row that has just mounted has nothing to transition FROM — a transition
 * needs two values and React gives it one. So the newest line gets a
 * keyframe for its first appearance only, with the same duration and curve
 * the step-down uses.
 *
 * fill-mode is deliberately left at `none`: once the keyframe finishes the
 * row falls back to its own `opacity: var(--tri-line-a)`, which is what
 * lets the transition above take over when the NEXT line pushes this one up
 * a rung. `forwards` would pin it at the keyframe's end value forever and
 * the ladder would never move again.
 */
.tri-transcript-line--new {
  animation: tri-transcript-in var(--tri-dur-transcript) var(--tri-ease-out);
}

@keyframes tri-transcript-in {
  from {
    opacity: 0;
  }
  to {
    opacity: var(--tri-line-a);
  }
}

/*
 * Reduced motion keeps the ladder — the opacities are the reading order,
 * and flattening them would lose which sentence is current — and drops
 * only the travel between rungs.
 */
@media (prefers-reduced-motion: reduce) {
  .tri-transcript-line {
    transition-duration: 1ms;
  }
  .tri-transcript-line--new {
    animation: none;
  }
}

.tri-surface--danger {
  --tri-1: var(--tri-red-1);
  --tri-2: var(--tri-red-2);
  --tri-3: var(--tri-red-3);
  --tri-4: var(--tri-red-4);
}

/* A tone is four variables. Nothing else changes — not the angle, not the
   alpha model, not the transition — so these read as the same material in a
   different colour rather than as four different surfaces. */
.tri-surface--ash {
  --tri-1: var(--tri-ash-1);
  --tri-2: var(--tri-ash-2);
  --tri-3: var(--tri-ash-3);
  --tri-4: var(--tri-ash-4);
}

.tri-surface--gold {
  --tri-1: var(--tri-gold-1);
  --tri-2: var(--tri-gold-2);
  --tri-3: var(--tri-gold-3);
  --tri-4: var(--tri-gold-4);
}

.tri-surface--indigo {
  --tri-1: var(--tri-indigo-1);
  --tri-2: var(--tri-indigo-2);
  --tri-3: var(--tri-indigo-3);
  --tri-4: var(--tri-indigo-4);
}

/*
 * The bright pair. Four variables like the others, plus the alpha ladder —
 * restated HERE rather than by setting --tri-alpha, because hover and active
 * write --tri-alpha themselves at a higher specificity and would drag a
 * bright button down to the dark tones' 0.7. Scoping the ladder keeps the
 * whole state model (rest → hover → press, the two-phase reveal) and only
 * moves where it starts: nearly opaque at rest, fully lit under the pointer.
 *
 * Refused (aria-disabled) needs nothing of its own: the shared rule below
 * takes the same gradient to 40%, which on a bright surface reads exactly as
 * meant — still green, visibly not armed yet.
 */
.tri-surface--go,
.tri-surface--caution {
  --tri-alpha-rest: 0.86;
  --tri-alpha-hover: 1;
  --tri-alpha-active: 1;
}
.tri-surface--go {
  --tri-1: var(--tri-go-1);
  --tri-2: var(--tri-go-2);
  --tri-3: var(--tri-go-3);
  --tri-4: var(--tri-go-4);
}
.tri-surface--caution {
  --tri-1: var(--tri-caution-1);
  --tri-2: var(--tri-caution-2);
  --tri-3: var(--tri-caution-3);
  --tri-4: var(--tri-caution-4);
}

.tri-surface--wide {
  --tri-angle: var(--tri-angle-wide);
}

/* Opaque fill — the slider's filled track. */
.tri-surface--solid {
  --tri-alpha: 1;
}

/*
 * State.
 *
 * A refused control is marked with aria-disabled, never the `disabled`
 * attribute: `disabled` drops the element out of the tab order and swallows
 * clicks entirely, so the user gets silence. aria-disabled keeps it
 * reachable and lets us answer the press with the nudge — same semantics
 * for assistive tech, but the interface admits it heard you.
 */
.tri-interactive[aria-disabled='true'] {
  opacity: 0.4;
  cursor: not-allowed;
}

/* Touch devices fire hover on tap, which lights the surface after the press
   has already ended. Gate it to real pointers. */
@media (hover: hover) and (pointer: fine) {
  .tri-interactive:hover:not([aria-disabled='true']) {
    --tri-alpha: var(--tri-alpha-hover);
    --tri-stroke-opacity: var(--tri-stroke-opacity-hover);
  }
  .tri-tone-danger:hover:not([aria-disabled='true']) {
    color: var(--tri-ink-danger-hover);
    --tri-stroke-color: rgb(234 199 198 / var(--tri-stroke-opacity-hover));
  }
}

/* Press: the control gives under the finger, so the UI feels like it heard.
   Scale, not colour — it survives on any tone and costs no paint. */
.tri-interactive:active:not([aria-disabled='true']) {
  transform: scale(var(--tri-press-scale));
}

/*
 * Ink tones. These live in CSS rather than inline styles so the danger
 * tone can lift its text on hover (#EAC7C6 → #FEC9C9) alongside the
 * gradient, the way the Figma variants do.
 */
.tri-tone {
  color: var(--tri-ink);
}
.tri-tone-danger {
  color: var(--tri-ink-danger);
}

/* Dark ink for the bright tones. The label's drop shadow goes too: it is
   there to lift light text off a gradient, and under dark text on a light
   surface it only smudges the letterforms. Doubled class so it outranks
   .tri-label, which is declared later in this file. */
.tri-tone-bright.tri-tone-bright {
  color: var(--tri-ink-on-bright);
  text-shadow: none;
  font-weight: 600;
}

/* Selected/active state for list surfaces. */
.tri-surface[data-active='true'] {
  --tri-alpha: var(--tri-alpha-active);
}

/* ------------------------------------------------------------------ */
/* Type                                                                */
/* ------------------------------------------------------------------ */

/*
 * Controls lowercase their labels ("the service", "delete account") but the
 * dashboard rows keep sentence case ("Today's Flow") — so casing is opted
 * into per component rather than baked in here.
 */
.tri-label {
  font-family: var(--tri-font);
  font-weight: var(--tri-weight);
  font-size: var(--tri-size);
  line-height: var(--tri-leading);
  letter-spacing: var(--tri-tracking);
  text-shadow: var(--tri-text-shadow);
}

.tri-panel-title,
.tri-control-heading {
  font-family: var(--tri-font-heading);
}

/* ------------------------------------------------------------------ */
/* F-05 — Tiers                                                        */
/* ------------------------------------------------------------------ */

/*
 * One lever for the whole system.
 *
 * A tier is nothing but a different set of values for the metrics block
 * above; every component reads those, so a tier reaches all of them at
 * once. This is the answer to "how does this scale when there are 181
 * components" — you never touch a component to change size.
 *
 * Three of them, not a continuous scale: each tier is a state somebody has
 * actually looked at, which an interpolation between two of them is not.
 *
 *   compact       a 13" laptop lid, close up
 *   comfortable   the default — a laptop on a desk, or a small monitor
 *   touch         a booth monitor read at arm's length or standing
 *
 * Deliberately NOT scaled by tier: list row heights and anything measured
 * in content (a transcript line, a verse). Those show *more* on a bigger
 * screen rather than growing, which is the whole point of capping the
 * chrome. See the note in Live.tsx.
 */

[data-density='compact'] {
  --tri-gap: 4px;
  --tri-control-h: 28px;
  --tri-control-pad-x: 10px;
  --tri-size-eyebrow: 9px;
  --tri-size-xs: 9px;
  --tri-control-size: 11px;
  --tri-size: 11px;
  --tri-size-sm: 10px;
  --tri-leading: 18px;
  --tri-field-h: 33px;
  --tri-bar-h: 33px;
  --tri-topbar-h: 41px;
  --tri-transcript-leading: 14px;
  --tri-field-h-sm: 28px;
  --tri-slider-h: 26px;
  --tri-option-h: 29px;
  --tri-row-h: 34px;
  --tri-card-w: 95px;
  --tri-handle-h: 14px;
  --tri-handle-h-active: 20px;
  --tri-radius-control: 5px;
  --tri-radius-surface: 8px;
}

/* comfortable is the :root block above — listed here only so the set of
   tiers reads as three things rather than two plus a default. */
[data-density='comfortable'] {
  --tri-gap: 4px;
  --tri-control-h: 32px;
  --tri-control-pad-x: 12px;
  --tri-size-eyebrow: 10px;
  --tri-size-xs: 10px;
  --tri-control-size: 12px;
  --tri-size: 12px;
  --tri-size-sm: 11px;
  --tri-leading: 20px;
  --tri-field-h: 38px;
  --tri-bar-h: 38px;
  --tri-topbar-h: 46px;
  --tri-transcript-leading: 15px;
  --tri-field-h-sm: 32px;
  --tri-slider-h: 30px;
  --tri-option-h: 33px;
  --tri-row-h: 39px;
  --tri-card-w: 108px;
  --tri-handle-h: 16px;
  --tri-handle-h-active: 23px;
  --tri-radius-control: 6px;
  --tri-radius-surface: 10px;
}

[data-density='touch'] {
  --tri-gap: 5px;
  --tri-control-h: 38px;
  --tri-control-pad-x: 16px;
  --tri-size-eyebrow: 11px;
  --tri-size-xs: 11px;
  --tri-control-size: 14px;
  --tri-size: 14px;
  --tri-size-sm: 12px;
  --tri-leading: 24px;
  --tri-field-h: 45px;
  --tri-bar-h: 45px;
  --tri-topbar-h: 53px;
  --tri-transcript-leading: 17px;
  --tri-field-h-sm: 37px;
  --tri-slider-h: 36px;
  --tri-option-h: 39px;
  --tri-row-h: 46px;
  --tri-card-w: 128px;
  --tri-handle-h: 19px;
  --tri-handle-h-active: 27px;
  --tri-radius-control: 7px;
  --tri-radius-surface: 12px;
}

