/*
 * Sandbox-only token overrides.
 *
 * Nothing in this file ships to the app. F-02 (dark/booth mode) and F-05
 * (density) are still undecided — this is where we look at them before
 * committing them to src/index.css. Both hang off data attributes on <html>
 * so the gallery toolbar can flip them live.
 */

/* ------------------------------------------------------------------ */
/* F-02 — booth mode (PROVISIONAL)                                     */
/* ------------------------------------------------------------------ */

[data-theme='dark'] {
  --color-paper: #0b0b0c;
  --color-ink: #ededec;
  --color-accent: #ffffff;
  --color-hairline: #26262a;
  --color-surface: #141416;
  --color-canvas: #000000;
}

/*
 * F-01 gap made visible: the accent flips from black to white between
 * themes, so "the text that sits on accent" cannot be a hardcoded white.
 * C-01 (Button) currently hardcodes `text-white` and therefore renders
 * white-on-white in booth mode — see the note on the Buttons sheet.
 */
:root {
  --color-on-accent: #ffffff;
}
[data-theme='dark'] {
  --color-on-accent: #0b0b0c;
}

/* ------------------------------------------------------------------ */
/* F-05 — tiers: no longer provisional, and no longer here             */
/* ------------------------------------------------------------------ */

/*
 * This used to set a root font-size per density, which scaled nothing that
 * mattered — every component states its own sizes in px, so the only thing
 * that moved was text that happened to be in rem.
 *
 * The real mechanism now lives in src/ui/tokens.css, where each tier
 * restates the metrics block. It ships with the app rather than being a
 * sandbox override, because it is the answer to how ~181 components resize
 * at all. The toolbar toggle just sets data-density on <html>.
 */

/* The gallery chrome itself must not resize with the specimens. */
[data-gallery-chrome] {
  font-size: 14px;
}

.tri-font-card {
  transition: box-shadow 150ms ease, transform 140ms cubic-bezier(0.23, 1, 0.32, 1);
}

.tri-font-card:active:not(:focus-visible):not([aria-disabled='true']) {
  transform: scale(0.97);
}

.tri-case-sample {
  display: grid;
  text-transform: none;
}

.tri-case-sample > span {
  grid-area: 1 / 1;
  opacity: 0;
