/*
 * "Find scripture" answers, over the preview's picture BAND: the pane's full
 * width, from the top of the picture to the top of the control row.
 *
 * The veil sits in the picture's wrapper (Live StageBox), which is centred and
 * narrower than the pane when the library is raised or the window is short,
 * so the negative left/right stretch it to 100cqw — the StageBox box, the
 * nearest size container. That is also what the veil's OWN padding and gap
 * resolve against; it is a container itself (find / size), so everything
 * inside it is sized in shares of the veil, not of a picture it may be wider
 * than.
 *
 * The layout steps down by the band's real shape — data-tier, from
 * lib/findTier — and anything a tier still misses scrolls inside the grid
 * instead of being cut through the middle of a line.
 */
.find-veil {
  position: absolute; top: 0; bottom: 0;
  left: calc((100% - 100cqw) / 2); right: calc((100% - 100cqw) / 2);
  z-index: 20;
  container: find / size;
  overflow: hidden;
  display: flex; flex-direction: column; gap: clamp(4px, 1.6cqw, 10px);
  padding: clamp(6px, 2.4cqw, 14px) clamp(8px, 3cqw, 18px);
  /* The seated picture's own corner (SlideCanvas seated), shape included. */
  border-radius: calc(var(--tri-radius-surface) - var(--tri-gap));
  corner-shape: var(--tri-corner);
  background: rgb(4 9 10 / .86);
  backdrop-filter: blur(6px);
  animation: find-veil-in 180ms var(--tri-ease-out) both;
}
.find-head { flex: none; display: flex; align-items: center; gap: 6px; min-height: 0; }
.find-heard {
  flex: 1; min-width: 0; overflow: hidden;
  display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2;
  font-size: clamp(10px, 1.9cqw, 13px); color: var(--tri-ink-muted);
}
.find-heard em { font-style: normal; color: var(--tri-ink); }
.find-edit { display: flex; flex-wrap: wrap; gap: 6px; flex: none; font-size: 11px; }
.find-edit textarea { flex: 1; min-width: 120px; resize: vertical; max-height: 100px; padding: 6px 8px; border: 1px solid rgb(229 243 242 / .2); border-radius: 5px; background: #111; color: var(--tri-ink); }
.find-edit button, .find-empty button { color: var(--tri-accent-yellow); cursor: pointer; padding: 6px; }
.find-edit button:disabled { opacity: .4; cursor: default; }
.find-edit :focus-visible, .find-empty button:focus-visible { outline: 2px solid var(--tri-accent-yellow); outline-offset: 1px; }
.find-empty { grid-column: 1 / -1; align-self: center; text-align: center; color: var(--tri-ink-muted); font-size: 12px; }
.find-basis { font-size: 10px; color: rgb(229 243 242 / .5); }
.find-veil:is([data-tier='tight'], [data-tier='micro']) .find-basis { display: none; }
.find-pager { flex: none; display: flex; align-items: center; gap: 4px; }
.find-round {
  display: grid; place-items: center; flex: none;
  width: clamp(22px, 4.4cqw, 30px); aspect-ratio: 1; border-radius: 999px;
  color: var(--tri-ink); background: rgb(229 243 242 / .08);
  box-shadow: inset 0 0 0 1px rgb(229 243 242 / .16);
  transition: background var(--tri-dur-state) var(--tri-ease-out), transform var(--tri-dur-press) var(--tri-ease-out);
}
.find-round:hover:not(:disabled) { background: rgb(229 243 242 / .16); }
.find-round:active:not(:disabled) { transform: scale(.94); }
.find-round:disabled { opacity: .3; }
.find-grid {
  flex: 1; min-height: 0;
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr));
  /* Rows share the band, one row for one or two answers — but never below
     what a card needs: a miss scrolls rather than clipping a line. */
  grid-auto-rows: minmax(min-content, 1fr);
  gap: clamp(4px, 1.6cqw, 10px);
  overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin;
}
.find-grid[data-count='1'] { grid-template-columns: minmax(0, 1fr); }
.find-card {
  position: relative; min-height: 0; overflow: hidden;
  display: flex; flex-direction: column; gap: clamp(2px, 1.2cqh, 6px);
  padding: clamp(6px, 3cqh, 14px) clamp(8px, 2.4cqw, 16px); text-align: left;
  border-radius: clamp(5px, 2cqw, 8px);
  border: 1px solid rgb(229 243 242 / .14);
  background: radial-gradient(ellipse at 0 0, rgb(var(--tri-teal-2) / .6), transparent 78%), #141818;
  animation: find-card-in 260ms var(--tri-ease-out) both;
  animation-delay: calc(var(--find-i) * 45ms);
  transition: border-color var(--tri-dur-state) var(--tri-ease-out), transform var(--tri-dur-press) var(--tri-ease-out);
}
.find-card:nth-child(2), .find-card:nth-child(3) {
  background: radial-gradient(ellipse at 100% 100%, rgb(var(--tri-teal-4) / .65), transparent 78%), #191817;
}
.find-card:hover { border-color: var(--tri-accent-yellow); }
.find-card:active { transform: scale(.985); }
.find-card:focus-visible { outline: 2px solid var(--tri-accent-yellow); outline-offset: 2px; }
/* One line, always: "Matthew / 18:10-13" broken over two read as two things. */
.find-ref {
  flex: none; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  font-size: clamp(11px, 2.5cqw, 17px); font-weight: 600; color: var(--tri-ink); line-height: 1.15;
}
.find-title {
  flex: none;
  font-size: clamp(8px, 1.45cqw, 10px); letter-spacing: .12em; text-transform: uppercase;
  color: rgb(229 243 242 / .45); overflow: hidden; white-space: nowrap; text-overflow: ellipsis;
}
.find-text {
  /* Whole lines — two, or what the tier allows below. Letting it fill the
     card cut the last line in half. */
  flex: none; overflow: hidden;
  display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2;
  font-size: clamp(9px, 1.75cqw, 12px); line-height: 1.5; color: var(--tri-ink-muted);
}
.find-go {
  position: absolute; right: 2.2cqw; bottom: 1.6cqw;
  /* On a short card it lands on the last line of text: a chip of the card's
     own ground keeps both readable. */
  padding: 1px 6px; border-radius: 4px; background: rgb(17 20 20 / .94);
  font-size: clamp(8px, 1.45cqw, 10px); letter-spacing: .1em; text-transform: uppercase;
  color: var(--tri-accent-yellow); opacity: 0;
  transition: opacity var(--tri-dur-state) var(--tri-ease-out);
}
.find-card:hover .find-go, .find-card:focus-visible .find-go { opacity: 1; }
.find-count { font-size: clamp(9px, 1.6cqw, 11px); font-variant-numeric: tabular-nums; color: var(--tri-ink-muted); }

/* The tiers (lib/findTier). The reference and the words come first; the
   story's title line is the first thing a smaller band gives up, then the
   second line of text. One or two answers on a roomy band are one tall row,
   which has room to read further into the passage. */
.find-veil[data-tier='full'] .find-grid:is([data-count='1'], [data-count='2']) .find-text { -webkit-line-clamp: 4; }
.find-veil[data-tier='compact'] .find-grid:is([data-count='3'], [data-count='4']) .find-title { display: none; }
.find-veil[data-tier='compact'] .find-grid:is([data-count='3'], [data-count='4']) .find-text { -webkit-line-clamp: 1; }
.find-veil:is([data-tier='tight'], [data-tier='micro']) .find-title { display: none; }
/* Micro: a band under 100px. On a wide one (a short window on a big screen)
   the head and type would still be sized for its width, so they stop at the
   small end. Gap, not padding, on the veil: the tier is read off the veil's
   content box, which padding would move and flip the tier back. */
.find-veil[data-tier='micro'] { gap: 4px; }
.find-veil[data-tier='micro'] .find-round { width: 22px; }
.find-veil[data-tier='micro'] .find-ref { font-size: clamp(11px, 2.5cqw, 13px); }
.find-veil[data-tier='micro'] .find-text { -webkit-line-clamp: 1; font-size: clamp(9px, 1.75cqw, 10px); }
.find-veil[data-tier='micro'] .find-card { padding-block: 3px; }

@keyframes find-veil-in { from { opacity: 0; } to { opacity: 1; } }
@keyframes find-card-in { from { opacity: 0; transform: translateY(6px) scale(.985); } to { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: reduce) {
  .find-veil, .find-card { animation-duration: 1ms; animation-delay: 0ms; }
  .find-card:active, .find-round:active:not(:disabled) { transform: none; }
}

/* Search feedback sits below the field, leaving the operator's words readable. */
.story-search { position: relative; display: flex; align-items: center; width: 100%; min-width: 0; }
.story-search__note {
  position: absolute;
  left: 0;
  right: 0;
  top: calc(100% + 4px);
  z-index: 30;
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 7px 10px;
  border: 1px solid rgb(229 243 242 / .12);
  border-radius: var(--tri-radius-control);
  background: #111;
  font-size: var(--tri-size-xs);
  color: rgb(229 243 242 / 0.5);
  overflow-wrap: anywhere;
}
.story-search__note button { margin-left: 6px; color: var(--tri-accent-yellow); text-decoration: underline; cursor: pointer; }
.story-search__note button:focus-visible { outline: 2px solid var(--tri-accent-yellow); outline-offset: 2px; }

/* Keep both scripture search outlines visible against the dark panel. */
.scripture-reference-search > .tri-rounded-control,
[data-scripture-browser] .story-search > .tri-rounded-control {
  border: 1px solid rgb(229 243 242 / 0.12);
}
.scripture-reference-search > .tri-rounded-control:focus-within,
[data-scripture-browser] .story-search > .tri-rounded-control:focus-within {
  border-color: rgb(229 243 242 / 0.28);
}

/* Shared dark glass with a faint dotted texture behind the content. */
.tri-dotted-surface {
  isolation: isolate;
  background: linear-gradient(165deg, rgb(var(--tri-teal-3) / 0.4), rgb(var(--tri-teal-1) / 0.66));
}

.tri-dotted-surface::before,
.tri-empty-surface::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background-image: radial-gradient(circle, rgb(229 235 243 / var(--tri-dot-alpha, 0.3)) 0.7px, transparent 0.95px);
  background-size: 7px 7px;
  mask-image: var(--tri-dot-patches);
  mask-size: 100% 100%;
  mask-repeat: no-repeat;
  animation: tri-dot-drift var(--tri-dot-duration, 48s) ease-in-out var(--tri-dot-delay, 0s) infinite;
}

.tri-empty-surface {
  position: relative;
  isolation: isolate;
  --tri-dot-alpha: 0.13;
}

/* Empty-state texture is static and much fainter than the glass cards. */
.tri-empty-surface::before {
  animation: none;
}

/* Move only the soft mask: the dot grid and card content stay still. */
.tri-library-tabs {
  --library-radius: calc(var(--tri-radius-control) + var(--tri-card-gap));
  padding: var(--tri-card-gap);
  border-radius: var(--library-radius);
  corner-shape: round;
}
.tri-library-tabs [role='tablist'] {
  border-radius: max(0px, calc(var(--library-radius) - var(--tri-card-gap)));
  corner-shape: round;
}

@keyframes tri-dot-drift {
  0%, 100% {
    mask-position: -2px 1px;
    opacity: 0.94;
  }
  33% {
    mask-position: 3px -1px;
    opacity: 1;
  }
  66% {
    mask-position: 1px 2px;
    opacity: 0.97;
  }
}

@media (prefers-reduced-motion: reduce) {
  .tri-dotted-surface::before {
    animation: none;
  }
}

/*
 * Word motion shared by the D-27 transcript designs.
 *
 * A word is keyed by its line id and index (see words.ts), so it mounts
 * ONCE — the arrival keyframe below therefore plays once per word, and a
 * re-render never restarts it. Its strength (softer while the engine is
 * still guessing, full once committed) is an opacity TRANSITION on the same
 * element, so committing a line brightens words in place.
 */
.tri-word {
  transition:
    opacity 240ms var(--tri-ease-out),
    color 240ms var(--tri-ease-out);
}

/* Arrival: out of a 2px blur, not out of nowhere, and quick — a word that
   takes longer to appear than it took to say reads as lag. */
/* `backwards` so a word given a stagger delay waits in its `from` state
   (invisible) rather than showing at full strength and then fading in. */
.tri-word--in {
  animation: tri-word-in 170ms var(--tri-ease-out) backwards;
}

@keyframes tri-word-in {
  from {
    opacity: 0;
    filter: blur(2px);
  }
}

/* A word the engine revised: the new spelling crossfades in over the old
   one's place rather than blinking. */
.tri-word-swap {
  animation: tri-word-swap 160ms var(--tri-ease-out);
}

@keyframes tri-word-swap {
  from {
    opacity: 0.25;
    filter: blur(1.5px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .tri-word--in,
  .tri-word-swap {
    animation-duration: 120ms;
  }
}

/*
 * Pages: the caption being turned away fades and lifts 4px, quickly, while
 * the new one arrives in its place. `forwards` because it is removed right
 * after — there is no resting state to fall back to.
 */
.tri-page-out {
  animation: tri-page-out 160ms var(--tri-ease-out) forwards;
  pointer-events: none;
}

@keyframes tri-page-out {
  to {
    opacity: 0;
    transform: translateY(-4px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .tri-page-out {
    animation-name: tri-page-fade;
  }
}

@keyframes tri-page-fade {
  to {
    opacity: 0;
  }
}

.operator-rail-split[data-resizing] { user-select: none; }
.operator-rail-split[data-resizing] .operator-rail-divider::before { background: rgb(229 243 242 / .36); }
.operator-rail-split[data-resizing] .operator-rail-handle { color: var(--tri-ink); }

.dashboard-bento {
  min-width: 0;
  min-height: 0;
  flex: 1;
  overflow: auto;
  overscroll-behavior: contain;
  container: dashboard / inline-size;
  --tri-size: 12px;
  --tri-size-sm: 11px;
  --tri-size-xs: 11px;
  --tri-control-h: 32px;
  --tri-bar-h: 38px;
}
.dashboard-bento__grid {
  position: relative;
  display: grid;
  min-height: 100%;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  grid-template-rows: minmax(274px, 1fr) minmax(310px, 1.1fr) minmax(246px, .9fr);
  gap: var(--tri-gap);
  padding: 1px;
}
.dashboard-bento__tile { min-width: 0; min-height: 0; }
.dashboard-bento section.tri-rounded-surface { background: #111; }
.dashboard-bento__status {
  display: grid;
  grid-template-rows: minmax(100px, .8fr) minmax(180px, 1.2fr);
  gap: var(--tri-gap);
  min-width: 0;
  min-height: 0;
}
.dashboard-bento .tri-panel-header { padding-inline: 16px; }
.dashboard-bento .tri-panel-title { font-size: 11px; letter-spacing: .14em; }
.dashboard-bento .tri-panel-body { min-width: 0; }
.dashboard-bento__readiness .tri-panel-body,
.dashboard-bento__connections .tri-panel-body { overflow-y: auto; }
.dashboard-bento__connections li { min-height: 26px; }
.dashboard-bento__readiness p { white-space: normal; overflow: visible; }
.dashboard-bento__readiness p:first-child { font-size: 15px; }
.dashboard-bento .preaching-card__header { padding: 12px 16px 14px; }
.dashboard-bento .preaching-card__title { font-size: 11px; }
.dashboard-bento .preaching-card__caption { font-size: 15px; }
.dashboard-bento .preaching-card__history { padding-inline: 16px; }
.dashboard-bento .preaching-card__live { margin-inline: 16px; }
.dashboard-bento .preaching-card__footer { padding: 12px 16px; }

/* Reflow by the space the dashboard owns, including the desktop app's chrome. */
@container dashboard (max-width: 1179px) {
  .dashboard-bento__grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    grid-template-rows: none;
    /* 288: readiness and connected stacked need 100 + 180 + the gap. A row
       no longer grows to its content (see the cell), so it has to start
       tall enough for the tallest card. */
    grid-auto-rows: minmax(288px, auto);
    align-content: start;
  }
  .dashboard-bento__status { grid-template-rows: minmax(100px, auto) minmax(180px, 1fr); }
}
@container dashboard (max-width: 899px) {
  .dashboard-bento__grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@container dashboard (max-width: 599px) {
  .dashboard-bento__grid { grid-template-columns: minmax(0, 1fr); }
}

.dashboard-bento .tri-panel-title,
.dashboard-bento .preaching-card__title {
  font-weight: 700;
  text-transform: uppercase;
}

/* Keep the title centered on the card, independently of right-side actions. */
.dashboard-bento .tri-panel-header--empty {
  position: relative;
  justify-content: center;
}
.dashboard-bento .tri-panel-header--empty > .tri-panel-heading {
  justify-content: center;
  max-width: 100%;
  padding-inline: 24px;
}
.dashboard-bento .tri-panel-header--empty > :not(.tri-panel-heading) {
  position: absolute;
  right: 16px;
}
.dashboard-bento .preaching-card--empty .preaching-card__header {
  position: relative;
  justify-content: center;
  text-align: center;
}
.dashboard-bento .preaching-card--empty .preaching-card__header > svg {
  position: absolute;
  right: 20px;
}

/* The QR keeps a usable square; controls never compete for its last pixels. */
.dashboard-bento .companion-face--stacked {
  display: grid;
  grid-template-rows: minmax(96px, 1fr) auto;
  justify-items: center;
  gap: 10px;
}
.dashboard-bento .companion-face--stacked .companion-face__qr {
  width: 112px;
  height: 112px;
  max-height: 100%;
  min-height: 96px;
  align-self: center;
}
.dashboard-bento .companion-face--stacked .companion-face__details {
  width: 100%;
  max-width: 260px;
  text-align: center;
}
.dashboard-bento .companion-face__details p { font-size: 11px; }

/* Both sides of a shared boundary use the same easing and duration.
   Real widths change together; the gutter follows the shared bento spacing. */
.dashboard-bento__cell {
  position: relative;
  min-width: 0;
  min-height: 0;
  /* A card is as tall as its row, never as tall as what is in it. The log,
     the notes and the transcript fill up while somebody preaches; sized by
     content, thirty caught verses in the log stretched every card on the
     page about six times over, because the three rows grow in proportion.
     Each card scrolls inside itself instead. Size only — paint containment
     would clip the hover growth, which reaches past the cell's own edge. */
  contain: size;
}
.dashboard-bento__motion,
.dashboard-bento__motion > * { width: 100%; height: 100%; min-width: 0; min-height: 0; }
.dashboard-bento__motion { position: relative; }
/* Hover growth is off for now (owner, 2026-10-08); see BentoGrid's sync().
@media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) {
  .dashboard-bento__motion {
    left: var(--bento-left, 0px);
    width: calc(100% + var(--bento-right, 0px) - var(--bento-left, 0px));
    transition: left var(--bento-motion-ms, 680ms) cubic-bezier(.4, 0, .2, 1), width var(--bento-motion-ms, 680ms) cubic-bezier(.4, 0, .2, 1);
  }
}
*/

/*
 * Motion for the empty-state drawings (D-30).
 *
 * The rule these all obey: an empty state is WAITING, and waiting is not
 * the same as loading. A spinner says "work is happening, stand by"; these
 * panels are not working, they are ready and unused. So nothing here spins,
 * pulses urgently, or runs a progress-shaped loop. Every animation is slow
 * (6–14s), low-amplitude, and never resolves — it is the visual equivalent
 * of a room breathing with nobody in it.
 *
 * All of it is CSS on SVG geometry that is already drawn: transforms,
 * opacity, and stroke-dashoffset. A short playback-rate ramp handles hover
 * entry and exit. At rest the animations pause and no JS frame loop runs.
 */

/* ------------------------------------------------------------------ */
/* Shared                                                              */
/* ------------------------------------------------------------------ */

/*
 * Every drawing sits in this box. transform-box/origin are set here once:
 * SVG children default to transform-origin at the USER SPACE origin, not
 * their own centre, so a scale on a <rect> without this flies off toward
 * the top-left instead of breathing in place.
 */
.tri-es-art * {
  transform-box: fill-box;
  transform-origin: center;
}

/* A horizontal line has no height, so fill-box gives it a degenerate box.
   The sweep moves in the SVG's own coordinates instead. */
.tri-es-sweep {
  transform-box: view-box;
}

/* ------------------------------------------------------------------ */
/* Run of service — the slots wait to be filled                        */
/* ------------------------------------------------------------------ */

/*
 * The dashes crawl. A dashed rect in this system means "a place where a
 * thing will go" (see CardArt's outer orbit), and animating the dash offset
 * makes that placeholder feel held open rather than abandoned — the same
 * read as a marching-ants selection, slowed to a fifth of the speed so it
 * is a drift rather than a march.
 *
 * Each slot crawls slower than the one above it: the top slot is the next
 * one to be filled, and the rail should feel like it is settling downward.
 */
.tri-es-slot--dashed {
  animation: tri-es-crawl 9s linear infinite;
}
.tri-es-slot--dashed.tri-es-d2 {
  animation-duration: 13s;
}

@keyframes tri-es-crawl {
  to {
    stroke-dashoffset: -14;
  }
}

/*
 * The first slot is solid — it is the one you are about to use — so it
 * breathes instead, very slightly, on the long cycle everything here shares.
 */
.tri-es-slot--first {
  animation: tri-es-breathe 7s var(--tri-ease-in-out) infinite;
}

@keyframes tri-es-breathe {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.62;
  }
}

/* ------------------------------------------------------------------ */
/* Catches, idle — the flat line                                       */
/* ------------------------------------------------------------------ */

/*
 * A true flat line is a dead signal, and an unmoving one reads as a frozen
 * UI rather than a quiet room. So the baseline gets the smallest possible
 * sign of life: a faint sweep of brightness travelling along it, once every
 * eight seconds. It is a scan, not a pulse — the panel is listening for
 * something to happen, and nothing is.
 */
.tri-es-sweep {
  animation: tri-es-sweep 8s var(--tri-ease-in-out) infinite;
}

/*
 * Translated in USER UNITS, not percent. A horizontal <line> has a
 * zero-height fill-box, and a percentage translate resolves against that
 * box — on some engines it collapses to nothing. The viewBox is 150 wide
 * and the sweep segment is 36, so ±98 carries it cleanly off both ends.
 */
/*
 * The sweep segment is drawn at x 8..30 and the baseline runs 8..142, so it
 * travels +112 to put its trailing edge at the line's far end and never
 * past it. It fades out well before then: a bright mark sitting at the end
 * of the axis reads as a value, not as a scan.
 */
@keyframes tri-es-sweep {
  0%,
  100% {
    transform: translateX(0);
    opacity: 0;
  }
  14% {
    opacity: 0.9;
  }
  62% {
    opacity: 0.9;
  }
  88% {
    opacity: 0;
  }
  99% {
    transform: translateX(112px);
  }
}

/*
 * The dashed ghost-peaks — where a catch WOULD have risen — fade in and out
 * on a long offset cycle, so the panel keeps suggesting the shape it is
 * waiting for without ever drawing it solidly enough to be misread as data.
 */
.tri-es-ghost {
  animation: tri-es-ghost 11s var(--tri-ease-in-out) infinite;
}
.tri-es-ghost.tri-es-d2 {
  animation-duration: 14s;
  animation-delay: -5s;
}

@keyframes tri-es-ghost {
  0%,
  100% {
    opacity: 0.1;
  }
  45% {
    opacity: 1;
  }
}

/* ------------------------------------------------------------------ */
/* Catches, listening — the field is live                              */
/* ------------------------------------------------------------------ */

/*
 * This is the one state on the page where something IS happening: the
 * engine is up and hearing a room. So it is the only drawing that twinkles
 * — each dot fading on its own cycle, with the per-dot duration and delay
 * set inline from the same seeded scatter that places it, so no two dots
 * are ever in phase. That irregularity is the whole effect: a field where
 * every dot blinked together would read as a strobe, and one where they
 * drift independently reads as noise being heard.
 */
.tri-es-dot {
  animation: tri-es-twinkle var(--tri-es-dur, 5s) var(--tri-ease-in-out) var(--tri-es-delay, 0s)
    infinite;
}

@keyframes tri-es-twinkle {
  0%,
  100% {
    opacity: var(--tri-es-lo, 0.15);
  }
  50% {
    opacity: var(--tri-es-hi, 0.7);
  }
}

/*
 * The listening baseline gets the same sweep as idle, but faster and
 * brighter: same gesture, more alive. The two panels sit side by side on
 * the Live screen often enough that the DIFFERENCE has to be legible, and
 * rate is the clearest axis for that — you read "faster" before you read
 * "brighter".
 */
.tri-es-sweep--live {
  animation-duration: 4.5s;
}

/* ------------------------------------------------------------------ */
/* Songs — the grid, gone dark                                         */
/* ------------------------------------------------------------------ */

/*
 * A query that matches nothing: the cards go out one after another, left to
 * right, and come back. Read as a search running along the row and finding
 * nothing in any of them. The stagger is per-column via an inline delay, so
 * the wave direction is the same as reading order.
 */
.tri-es-card {
  animation: tri-es-dim 6s var(--tri-ease-in-out) var(--tri-es-delay, 0s) infinite;
}

@keyframes tri-es-dim {
  0%,
  100% {
    opacity: 1;
  }
  40% {
    opacity: 0.3;
  }
}

/* ------------------------------------------------------------------ */
/* Recent services — the chart before there is a line                   */
/* ------------------------------------------------------------------ */

/*
 * The dashed columns rise from the baseline and settle back, one after the
 * other — the chart rehearsing the shape it will have once services exist.
 * scaleY from the bottom, so they grow out of the axis rather than out of
 * their own middles.
 */
.tri-es-col {
  transform-origin: bottom;
  animation: tri-es-rise 9s var(--tri-ease-in-out) var(--tri-es-delay, 0s) infinite;
}

@keyframes tri-es-rise {
  0%,
  100% {
    transform: scaleY(0.18);
    opacity: 0.25;
  }
  45%,
  60% {
    transform: scaleY(1);
    opacity: 1;
  }
}

/* The rail's spine: the slowest crawl of the three rail gestures, because
   it is the run as a whole rather than any one slot. -14 is exactly two
   periods of a "2 5" dash, so it loops with no visible jump. */
.tri-es-spine {
  animation: tri-es-crawl 18s linear infinite;
}

/* ------------------------------------------------------------------ */
/* Transcript — the room above the pill                                */
/* ------------------------------------------------------------------ */

/*
 * NOT a crawl. The run rail's slots crawl because they are places a card
 * gets dropped into; a line of speech is not dropped, it accumulates. So
 * these lines do not travel — they strengthen and fade on their own
 * cycles, the rhythm of a sentence that keeps almost starting.
 *
 * Co-prime-ish durations at negative delays mean no two lines are ever in
 * step, so the stack never pulses as a unit. And the rates are deliberately
 * NOT graded by depth the way the run rail's are — a rate gradient is the
 * rail's signature, and a second panel borrowing it dilutes both.
 */
.tri-es-utter {
  animation: tri-es-breathe var(--tri-es-dur, 11s) var(--tri-ease-in-out)
    var(--tri-es-delay, 0s) infinite;
}
.tri-es-t0 { --tri-es-dur: 11s; --tri-es-delay: 0s; }
.tri-es-t1 { --tri-es-dur: 13s; --tri-es-delay: -3.5s; }
.tri-es-t2 { --tri-es-dur: 12s; --tri-es-delay: -7s; }
.tri-es-t3 { --tri-es-dur: 14s; --tri-es-delay: -2s; }
.tri-es-t4 { --tri-es-dur: 13s; --tri-es-delay: -9s; }

/* Where the next word would start, on the longest cycle on the sheet. */
.tri-es-next {
  animation: tri-es-rest 9s var(--tri-ease-in-out) infinite;
}

@keyframes tri-es-rest {
  0%,
  100% {
    opacity: 0.34;
  }
  50% {
    opacity: 0.12;
  }
}

/* ------------------------------------------------------------------ */
/* Companion — the square waiting for a code                           */
/* ------------------------------------------------------------------ */

/* The square is real and ready, so it breathes — the same reason the run
   rail's first slot does. The register drifts on the slowest crawl in the
   set, because there is no next action here: the code appears when the
   service opens, not when anyone presses anything. */
.tri-es-qr-frame {
  animation: tri-es-breathe 9s var(--tri-ease-in-out) infinite;
}
.tri-es-qr-grid {
  animation: tri-es-crawl 16s linear infinite;
}
.tri-es-qr-grid.tri-es-d2 {
  animation-duration: 21s;
}

/* ------------------------------------------------------------------ */
/* Notifications — the gutter                                          */
/* ------------------------------------------------------------------ */

/* Slowest crawl on the sheet. Nothing here translates and nothing moves
   downward: the log's real arrival gesture is a translateY, and borrowing
   it to mean "nothing has happened" reads as a bug rather than a choice. */
.tri-es-slot--dashed.tri-es-d3 {
  animation-duration: 17s;
}

/* ------------------------------------------------------------------ */
/* The kept room — rows that fade rather than travel                   */
/* ------------------------------------------------------------------ */

/*
 * A dash-crawl on a line that starts at a fixed margin reads as extension
 * toward the right edge — a gesture with a destination, which is the
 * spinner failure at 16s instead of 1s. Fading has no destination: the card
 * suggests rows and lets them go, forever, which is what a permanently kept
 * space does. The slowest thing on the page, because this is the only card
 * that will never fill.
 */
.tri-es-kept {
  animation: tri-es-hold 16s var(--tri-ease-in-out) var(--tri-es-delay, 0s) infinite;
}

/*
 * A gentler trough than tri-es-ghost's 0.1. These rows are already the
 * dimmest marks on the sheet (0.20 down to 0.13), and multiplying that by
 * 0.1 took them to nothing — the card read as genuinely blank for half of
 * every cycle, which is the broken look this drawing exists to avoid.
 * Floors at 0.45 instead: the rows never leave, they only soften.
 */
@keyframes tri-es-hold {
  0%,
  100% {
    opacity: 0.45;
  }
  50% {
    opacity: 1;
  }
}

/* ------------------------------------------------------------------ */
/* Sermon notes — the outline accretes                                 */
/* ------------------------------------------------------------------ */

/*
 * Notes do not arrive on a signal, so nothing sweeps and nothing scans.
 * They accrete, unevenly, over forty minutes. The dashes drift RIGHTWARD —
 * the direction a line is written, not the direction marching ants travel —
 * at three rates by depth, so the eye settles on the top level, which is an
 * outline's reading order.
 */
.tri-es-outline {
  animation: tri-es-drift 11s linear infinite;
}
.tri-es-o1 { animation-duration: 13s; }
.tri-es-o2 { animation-duration: 10s; }
.tri-es-o3 { animation-duration: 8s; }

/* 9 is not arbitrary: the dasharrays here are "4 5" and "3 4", periods of
   9 and 7. A 9 offset loops seamlessly on the points; the sub-lines drift
   through their own period without a visible jump because they are dimmer
   and shorter. */
@keyframes tri-es-drift {
  to {
    stroke-dashoffset: 9;
  }
}

/* ------------------------------------------------------------------ */
/* The catches ghosts — a third peak                                   */
/* ------------------------------------------------------------------ */

/* 11 / 14 / 17 with scattered delays: the three never coincide inside the
   ten minutes a booth looks at this before a service. */
.tri-es-ghost.tri-es-d3 {
  animation-duration: 17s;
  animation-delay: -9s;
}

/* ------------------------------------------------------------------ */
/* Reduced motion                                                      */
/* ------------------------------------------------------------------ */

/*
 * Everything above is decoration on a state that is already fully told by
 * its drawing and its sentence, so under reduced motion it all simply
 * stops. Nothing is shortened or softened — there is no information in the
 * movement to preserve, which is the test for whether an animation may be
 * removed outright.
 */
@media (prefers-reduced-motion: reduce) {
  .tri-es-slot--dashed,
  .tri-es-slot--first,
  .tri-es-spine,
  .tri-es-sweep,
  .tri-es-ghost,
  .tri-es-dot,
  .tri-es-card,
  .tri-es-col,
  .tri-es-utter,
  .tri-es-next,
  .tri-es-qr-frame,
  .tri-es-qr-grid,
  .tri-es-kept,
  .tri-es-outline {
    animation: none;
  }
  /* The columns' resting transform is mid-animation, so it has to be
     restored explicitly or they sit collapsed at 18%. */
  .tri-es-col {
    transform: none;
  }
  .tri-es-sweep {
    opacity: 0;
  }
}

/* ------------------------------------------------------------------ */
/* Motion marks — yui540's demos, ported whole                         */
/* ------------------------------------------------------------------ */

/*
 * Everything under this banner is copied from the files in
 * design/motion/yui540/source (MIT, © 2026 yui540): her selectors
 * renamed into this app's namespace, her keyframe values and easings
 * kept to the digit. Where a demo played once (two chained animations
 * with delays), the chain is merged into one infinite timeline — the
 * same values at the same relative spacing, expressed as percentages of
 * a cycle with a rest, so each segment keeps its own ease exactly as
 * the chain gave it.
 *
 * Colour is the one translation: her grey ramp on white becomes the
 * same ramp in this app's ink on near-black, darkest-on-white mapping
 * to brightest-on-dark. The variables keep her hex names so any port
 * can be read against its source file.
 */
.tri-ma {
  --g666: rgb(229 243 242 / 0.62);
  --g777: rgb(229 243 242 / 0.55);
  --g888: rgb(229 243 242 / 0.48);
  --g999: rgb(229 243 242 / 0.42);
  --gaaa: rgb(229 243 242 / 0.36);
  --gbbb: rgb(229 243 242 / 0.3);
  --gccc: rgb(229 243 242 / 0.25);
  --ge0: rgb(229 243 242 / 0.12);
  /* Printed marks on a light sheet — the QR modules, the note rules. */
  --gink: rgb(10 12 12 / 0.55);
}

/* Her 320 stage, scaled into whatever box the card gives it. */
.tri-yui {
  position: relative;
}
.tri-yui__stage {
  position: absolute;
  top: 0;
  left: 0;
  width: 320px;
  height: 320px;
  transform-origin: top left;
  display: grid;
  place-content: center;
}

/*
 * Start paused before the first paint. useEmptyHover controls the native
 * timelines, including pseudo-elements, and brakes their speed on leave.
 */
.tri-play-hover .tri-ma {
  opacity: 0.55;
  transition: opacity 480ms var(--tri-ease-out);
}
.tri-play-hover[data-empty-active='true'] .tri-ma {
  opacity: 1;
}
/*
 * !important, and it is load-bearing. Every port below sets its motion
 * with the `animation:` SHORTHAND, exactly as yui540 wrote it — and the
 * shorthand resets animation-play-state to `running`. Those rules come
 * later in this file at equal specificity, so without this they win the
 * cascade and a hover-gated demo plays forever. Rewriting her shorthands
 * into longhand would have meant editing every ported rule, which is the
 * one thing these ports are not allowed to do.
 */
.tri-play-hover :is(.tri-ma, .tri-ma *, .tri-es-art, .tri-es-art *),
.tri-play-hover .tri-ma *::before,
.tri-play-hover .tri-ma *::after {
  animation-play-state: paused !important;
}

/* ------------------------------------------------------------------ */
/* Run of service — pop-up stack (2026-04-18/tips-4)                   */
/* ------------------------------------------------------------------ */

.tri-pop {
  position: absolute;
  bottom: 35%;
  width: 100%;
  display: grid;
  row-gap: 3px;
  justify-items: center;
  align-content: end;
}
.tri-pop__block {
  position: relative;
  width: 120px;
  height: 40px;
  border-radius: 8px;
  transform-origin: bottom center;
}
/* Her jump (0.7s, delay 0.3s), rebaked onto a 2.8s cycle: 0.3s→10.7%,
   then her 40/60/80% frames at 20.7/25.7/30.7, landed by 35.7. From and
   to are both translateY(0), so the loop has no seam. */
.tri-pop__block:nth-child(1) {
  background-color: var(--gaaa);
  animation: tri-pop-jump 2.8s ease-in-out infinite both;
}
/* The entrance plays once when the card is first hovered. */
.tri-pop__block:nth-child(2) {
  background-color: var(--g888);
  animation: tri-pop-push 0.5s ease-in-out 0.2s both;
}
@keyframes tri-pop-jump {
  0%,
  10.7% {
    transform: translateY(0);
  }
  20.7% {
    transform: translateY(-40%) rotate(6deg);
  }
  25.7% {
    transform: translateY(0%);
  }
  30.7% {
    transform: translateY(-20%) rotate(-3deg);
  }
  35.7%,
  100% {
    transform: translateY(0);
  }
}
@keyframes tri-pop-push {
  from {
    height: 0;
  }
  60% {
    height: 48px;
  }
  to {
    height: 40px;
  }
}

/* ------------------------------------------------------------------ */
/* Catches idle — dominoes (2026-04-18/tips-2)                         */
/* ------------------------------------------------------------------ */

.tri-dom {
  display: grid;
  column-gap: 20px;
  grid-template-columns: repeat(4, auto);
  place-content: center;
}
.tri-dom__block {
  position: relative;
  width: 20px;
  aspect-ratio: 20/60;
  border-radius: 5px;
  transform-origin: right bottom;
}
/* Her four falls (0.65s at delays 0.2–0.5s, end angles 60/61/66/90 with
   the rock-back at 80%), rebaked onto one 3.8s cycle; the row stands
   back up together toward 75%, last tile first. */
.tri-dom__block:nth-child(1) {
  background-color: var(--g777);
  animation: tri-dom-1 3.8s ease-in-out infinite both;
}
.tri-dom__block:nth-child(2) {
  background-color: var(--gbbb);
  animation: tri-dom-2 3.8s ease-in-out infinite both;
}
.tri-dom__block:nth-child(3) {
  background-color: var(--gaaa);
  animation: tri-dom-3 3.8s ease-in-out infinite both;
}
.tri-dom__block:nth-child(4) {
  background-color: var(--g999);
  animation: tri-dom-4 3.8s ease-in-out infinite both;
}
@keyframes tri-dom-1 {
  0%, 5.3% { transform: rotate(0deg); }
  15.5% { transform: rotate(60deg); }
  18.9% { transform: rotate(55deg); }
  22.4%, 67.1% { transform: rotate(60deg); }
  75%, 100% { transform: rotate(0deg); }
}
@keyframes tri-dom-2 {
  0%, 7.9% { transform: rotate(0deg); }
  18.2% { transform: rotate(61deg); }
  21.6% { transform: rotate(56deg); }
  25%, 64.5% { transform: rotate(61deg); }
  75%, 100% { transform: rotate(0deg); }
}
@keyframes tri-dom-3 {
  0%, 10.5% { transform: rotate(0deg); }
  20.8% { transform: rotate(66deg); }
  24.2% { transform: rotate(60deg); }
  27.6%, 61.8% { transform: rotate(66deg); }
  75%, 100% { transform: rotate(0deg); }
}
@keyframes tri-dom-4 {
  0%, 13.2% { transform: rotate(0deg); }
  23.4% { transform: rotate(90deg); }
  26.8% { transform: rotate(85deg); }
  30.3%, 59.2% { transform: rotate(90deg); }
  75%, 100% { transform: rotate(0deg); }
}

/* ------------------------------------------------------------------ */
/* Transcript — scroll unroll (2026-04-25/tips-1)                      */
/* ------------------------------------------------------------------ */

/* Her .makimono, name for name. The whole demo ran 0→2.7s (draw at 0,
   reverse chains at 1.7s); everything below is that timeline on a 3.4s
   cycle — 1s draw = 29.4%, the 1.7s turn = 50%, the reverse done at
   79.4%, then rest. */
/* All six of the scroll's animations share one -1.2s delay: a paused
   hover demo sits at its start, and this one's start is everything
   rolled away. Parked at 35%% the scroll rests open with its lines up,
   and her stagger is untouched — it lives in the baked percentages. */
.tri-scroll {
  position: relative;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) scale(1.18);
  width: fit-content;
}
.tri-scroll__title {
  position: relative;
  white-space: nowrap;
  overflow: hidden;
  font-size: 0;
}
/* Her glyph spans, as blank blocks — the words this panel is waiting
   for belong to the pill under it, which already carries the sentence. */
.tri-scroll__title span {
  display: inline-block;
  width: 24px;
  height: 30px;
  margin: 0 3px;
  border-radius: 6px;
  background-color: var(--g666);
  transform-origin: bottom center;
  transform: translateY(100%);
}
.tri-scroll__title span:nth-child(1) { animation: tri-scroll-s1 3.4s ease-in-out -1.2s infinite both; }
.tri-scroll__title span:nth-child(2) { animation: tri-scroll-s2 3.4s ease-in-out -1.2s infinite both; }
.tri-scroll__title span:nth-child(3) { animation: tri-scroll-s3 3.4s ease-in-out -1.2s infinite both; }
.tri-scroll__title span:nth-child(4) { animation: tri-scroll-s4 3.4s ease-in-out -1.2s infinite both; }
/* Her slide-in (0.55s, the -8% overshoot with the 0.95/1.15 stretch at
   60%) and slide-out (0.3s to 100% with the 1.2/0.6 squash), at her
   stagger: in at 0.65/0.55/0.45/0.35s, out at 1.85–2.15s. */
@keyframes tri-scroll-s1 {
  0%, 19.1% { transform: translateY(100%); }
  28.8% { transform: translateY(-8%) scale(0.95, 1.15); }
  35.3%, 54.4% { transform: translateY(0); }
  63.2% { transform: translateY(100%) scale(1.2, 0.6); }
  100% { transform: translateY(100%); }
}
@keyframes tri-scroll-s2 {
  0%, 16.2% { transform: translateY(100%); }
  25.9% { transform: translateY(-8%) scale(0.95, 1.15); }
  32.4%, 57.4% { transform: translateY(0); }
  66.2% { transform: translateY(100%) scale(1.2, 0.6); }
  100% { transform: translateY(100%); }
}
@keyframes tri-scroll-s3 {
  0%, 13.2% { transform: translateY(100%); }
  22.9% { transform: translateY(-8%) scale(0.95, 1.15); }
  29.4%, 60.3% { transform: translateY(0); }
  69.1% { transform: translateY(100%) scale(1.2, 0.6); }
  100% { transform: translateY(100%); }
}
@keyframes tri-scroll-s4 {
  0%, 10.3% { transform: translateY(100%); }
  20% { transform: translateY(-8%) scale(0.95, 1.15); }
  26.5%, 63.2% { transform: translateY(0); }
  72.1% { transform: translateY(100%) scale(1.2, 0.6); }
  100% { transform: translateY(100%); }
}
.tri-scroll__line {
  position: absolute;
  bottom: -40%;
  left: -40%;
  width: 180%;
  height: 20%;
  overflow: hidden;
  border-radius: 999px;
}
.tri-scroll__line::before {
  content: "";
  display: block;
  position: absolute;
  inset: 0;
  background-color: var(--gccc);
  border-radius: 999px;
  animation: tri-scroll-line 3.4s ease-in-out -1.2s infinite both;
}
@keyframes tri-scroll-line {
  0% { transform: translateX(101%); }
  29.4%, 50% { transform: translateX(0); }
  79.4%, 100% { transform: translateX(101%); }
}
.tri-scroll__roll {
  position: absolute;
  bottom: -40%;
  right: -70%;
  height: 160%;
  aspect-ratio: 1;
  background: linear-gradient(to bottom, var(--gccc) 0 50%, var(--gaaa) 0);
  border-radius: 999px;
  overflow: hidden;
  animation: tri-scroll-roll 3.4s ease-in-out -1.2s infinite both;
}
.tri-scroll__roll::before {
  content: "";
  display: block;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 40%;
  aspect-ratio: 1;
  border-radius: 999px;
  background-color: var(--g666);
}
@keyframes tri-scroll-roll {
  0% { transform: translateX(0) rotate(180deg); }
  29.4%, 50% { transform: translateX(-420%) rotate(-180deg); }
  79.4%, 100% { transform: translateX(0) rotate(180deg); }
}

/* ------------------------------------------------------------------ */
/* Companion — rolling blocks (2026-05-14/tips-3)                      */
/* ------------------------------------------------------------------ */

/* Her loop untouched: cycle, angles, the left block's whole feed. Her
   ::before faces are real divs here so the QR furniture can ride them;
   her ground sheet is gone — the square button is the ground. */
.tri-roll {
  position: absolute;
  inset: 0;
  transform: translate(0, -6%) scale(1.4);
}
.tri-roll__box {
  --size: 70px;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: calc(var(--size) * 2);
  height: var(--size);
}
.tri-roll__main {
  position: relative;
  width: var(--size);
  height: var(--size);
  transform-origin: right bottom;
  animation: tri-roll-right 1.9s ease-in-out -0.85s infinite both;
}
.tri-roll__main-face {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  border-radius: 20%;
  background-color: var(--g999);
  transform-origin: right top;
  animation: tri-roll-right-inner 1.9s ease-in-out -0.85s infinite both;
}
@keyframes tri-roll-right {
  0%, 10.53% { transform: rotate(0deg); }
  28.95%, 100% { transform: rotate(90deg); }
}
@keyframes tri-roll-right-inner {
  0%, 23.68% { transform: rotate(0deg); }
  31.58% { transform: rotate(8deg); }
  39.47%, 100% { transform: rotate(0deg); }
}
.tri-roll__left {
  position: absolute;
  bottom: 0;
  left: 0;
  width: var(--size);
  height: var(--size);
  transform: translateX(-30%);
}
.tri-roll__left-face {
  position: absolute;
  bottom: 0;
  left: 50%;
  width: 100%;
  height: 100%;
  background-color: var(--gccc);
  border-radius: 20%;
  animation: tri-roll-feed 1.9s ease-in-out -0.85s infinite both;
}
@keyframes tri-roll-feed {
  0%, 10.53% {
    width: 100%;
    height: 100%;
    transform: translateX(-50%) translateY(100%);
  }
  29.47% {
    width: 90%;
    height: 125%;
    transform: translateX(-50%) translateY(0);
  }
  42.11%, 52.63% {
    width: 100%;
    height: 100%;
    transform: translateX(-50%) translateY(0);
  }
  68.42% {
    width: 90%;
    height: 120%;
    transform: translateX(-50%) translateY(0);
  }
  84.21%, 100% {
    width: 120%;
    height: 60%;
    transform: translateX(-50%) translateY(100%);
  }
}
/* The code furniture: a finder ring on the feeder, modules on the
   roller — printed in the app's own dark, like ink on the grey. */
.tri-roll__finder {
  position: absolute;
  top: 15%;
  left: 15%;
  width: 32%;
  aspect-ratio: 1;
  border: 5px solid var(--gink);
}
.tri-roll__dot {
  position: absolute;
  width: 16%;
  aspect-ratio: 1;
  background-color: var(--gink);
}
.tri-roll__dot--a { right: 18%; bottom: 18%; }
.tri-roll__dot--b { top: 15%; left: 15%; }
.tri-roll__dot--c { top: 15%; right: 20%; }
.tri-roll__dot--d { bottom: 20%; left: 22%; }
.tri-roll__dot--e { top: 45%; left: 48%; }

/* ------------------------------------------------------------------ */
/* Sermon notes — tissue box (2026-05-14/tips-1)                       */
/* ------------------------------------------------------------------ */

/* Hers verbatim, wrapper scale folded onto the element; each sheet
   carries three rules — every tissue a page of the outline. */
.tri-tissue {
  position: relative;
  width: 150px;
  height: 60px;
  transform: scale(1.4);
}
.tri-tissue::before,
.tri-tissue::after {
  content: "";
  position: absolute;
  z-index: 1;
}
.tri-tissue::before {
  inset: 0;
  background-color: var(--g999);
  border-radius: 20px 20px 5px 5px;
}
.tri-tissue::after {
  bottom: 0;
  left: 0;
  width: 100%;
  height: 50%;
  background-color: var(--g777);
  border-radius: 0 0 5px 5px;
}
.tri-tissue__paper1,
.tri-tissue__paper2 {
  position: absolute;
  bottom: 99%;
  left: 50%;
  width: 70%;
  height: 50%;
  transform: translate(-50%, 0);
  transform-origin: center bottom;
  background-color: rgb(229 243 242 / 0.5);
  clip-path: polygon(0 0, 100% 0, 98% 100%, 2% 100%);
}
.tri-tissue__paper1 {
  animation: tri-tissue-pull 1.4s ease-in-out 0s infinite both;
}
.tri-tissue__paper2 {
  animation: tri-tissue-push 1.4s ease-in-out 0s infinite both;
}
@keyframes tri-tissue-pull {
  0%, 14.29% {
    opacity: 1;
    height: 50%;
    transform: translate(-50%, 0);
  }
  37.5% {
    height: 80%;
    transform: translate(-50%, 0);
  }
  51.43% {
    opacity: 1;
  }
  60.71%, 100% {
    opacity: 0;
    height: 80%;
    transform: translate(-50%, -200%) rotate(20deg);
  }
}
@keyframes tri-tissue-push {
  0%, 25% {
    height: 50%;
    bottom: 0;
  }
  55% {
    height: 80%;
  }
  75%, 100% {
    height: 50%;
    bottom: 99%;
  }
}
.tri-tissue__rule {
  position: absolute;
  left: 18%;
  height: 9%;
  min-height: 2px;
  border-radius: 99px;
  background-color: var(--gink);
}

/* ------------------------------------------------------------------ */
/* Notifications — orbit (2026-05-02/tips-4)                           */
/* ------------------------------------------------------------------ */

.tri-orbit {
  position: absolute;
  inset: 0;
  display: grid;
  place-content: center;
}
.tri-orbit__box {
