}
.tri-orbit__small::before {
  content: "";
  display: block;
  position: absolute;
  top: 0;
  left: 50%;
  width: 40%;
  aspect-ratio: 1;
  background-color: var(--gaaa);
  border-radius: 50%;
  transform: translate(-50%, 0);
}
.tri-orbit__orbit {
  position: absolute;
