}
@keyframes tri-orbit-small {
  from { transform: rotate(0); }
  80%, to { transform: rotate(360deg); }
}

/* ------------------------------------------------------------------ */
/* The kept room — balancing blocks (2026-04-18/tips-1)                */
/* ------------------------------------------------------------------ */

/* Her three pieces, entry tilt and three-frame wobble merged onto a
   3.2s cycle: each ends where it began, so the settle repeats. Her
   half-and-half gradients kept, in grey. */
.tri-bal {
  display: grid;
  justify-items: center;
}
.tri-bal__large {
  position: relative;
  width: 65px;
  aspect-ratio: 1;
  border-radius: 50%;
  background: linear-gradient(to top, var(--gaaa) 0 50%, var(--g777) 0);
  animation: tri-bal-large 3.2s ease-in-out infinite both;
}
@keyframes tri-bal-large {
  0% { transform: translateX(0); }
  21.9% { transform: translate(50%, 3%) rotate(30deg); }
  40.6% { transform: translate(-50%, 3%) rotate(-35deg); }
  50% { transform: translate(10%, 1%) rotate(10deg); }
  59.4%, 100% { transform: translateX(0); }
}
.tri-bal__bar {
  width: 120px;
  height: 12px;
  border-radius: 999px;
  background-color: var(--gaaa);
  animation: tri-bal-bar 3.2s ease-in-out infinite both;
}
@keyframes tri-bal-bar {
  0% { transform: translateX(0); }
  18.8% { transform: translateX(8%) rotate(6deg); }
  37.5% { transform: translateX(-8%) rotate(-6deg); }
  46.9% { transform: translateX(2%) rotate(2deg); }
  56.3%, 100% { transform: translateX(0); }
}
.tri-bal__small {
  position: relative;
  width: 35px;
  aspect-ratio: 1;
  border-radius: 50%;
  background: linear-gradient(to top right, var(--gaaa) 0 50%, var(--g777) 0);
  animation: tri-bal-small 3.2s ease-in-out infinite both;
}
@keyframes tri-bal-small {
  0% { transform: translateX(0); }
  15.6% { transform: translateX(30%) rotate(25deg); }
  34.4% { transform: translateX(-30%) rotate(-25deg); }
  43.8% { transform: translateX(10%) rotate(5deg); }
  53.1%, 100% { transform: translateX(0); }
}

/* ------------------------------------------------------------------ */
/* ON AIR — loading-3's equalizer bars (2025-03-11/loading-3.svg)      */
/* ------------------------------------------------------------------ */

/* Her cascade verbatim, including the unitless delay on 6n that CSS
   drops — the bar pattern this produces is the one her loader shows. */
.tri-eq * {
  transform-box: fill-box;
  transform-origin: center;
}
.tri-eq__wrap {
  animation: tri-eq-outer 1.1s ease-in-out infinite both;
}
.tri-eq__wrap:nth-child(2n) {
  --scale-y: 2.25;
  animation-delay: 0.5s;
}
.tri-eq__wrap:nth-child(3n) {
  --scale-y: 3.5;
  animation-delay: 0.9s;
}
.tri-eq__wrap:nth-child(4n) {
  --scale-y: 2.5;
  animation-delay: 1s;
}
.tri-eq__wrap:nth-child(5n) {
  --scale-y: 3.25;
  animation-delay: 0.75s;
}
.tri-eq__wrap:nth-child(6n) {
  --scale-y: 4.5;
  animation-delay: 1.2;
}
.tri-eq__wrap:nth-child(10n) {
  --scale-y: 5;
  animation-delay: 0.8s;
}
.tri-eq__line {
  animation: tri-eq-inner 0.15s ease-in-out 0s infinite both;
}
.tri-eq__wrap:nth-child(2n) .tri-eq__line {
  animation-delay: 0.1s;
}
@keyframes tri-eq-outer {
  from, 30%, to {
    transform: scaleY(1);
  }
  15% {
    transform: scaleY(var(--scale-y));
  }
}
@keyframes tri-eq-inner {
  from, to {
    transform: scaleY(1);
  }
  50% {
    transform: scaleY(1.5);
  }
}

/* ------------------------------------------------------------------ */
/* The bento's open cue — the expand arrow (2026-05-02/tips-1)         */
/* ------------------------------------------------------------------ */

/* Scales in on tile hover, breathes while it stays,
   scales back out on leave. */
.tri-cue {
  display: block;
  width: 14px;
  height: 14px;
  opacity: 0;
  transform: scale(0);
  transition:
    transform 280ms var(--tri-ease-out),
    opacity 280ms var(--tri-ease-out);
}
.group\/tile:hover .tri-cue {
  opacity: 1;
  transform: scale(1);
}
.tri-cue__icon {
  color: rgb(229 243 242 / 0.75);
  animation: tri-cue-pulse 0.8s ease-in-out infinite both;
  animation-play-state: paused;
}
.group\/tile:hover .tri-cue__icon {
  animation-play-state: running;
}
@keyframes tri-cue-pulse {
  from, to {
    transform: scale(1);
  }
  50% {
    transform: scale(1.15);
  }
  75% {
    transform: scale(0.95);
  }
}

/* Every port stops outright under reduced motion — none of the movement
   carries information the card's sentence does not. */
@media (prefers-reduced-motion: reduce) {
  .tri-es-art,
  .tri-es-art *,
  .tri-ma,
  .tri-ma *,
  .tri-ma *::before,
  .tri-ma *::after,
  .tri-cue__icon {
    animation: none !important;
  }
  .tri-cue {
    transition: none;
  }
}

/* Reserve readable artwork and copy independently; a cramped card scrolls
   instead of collapsing the SVG to a speck or clipping its action. */
.tri-empty-mark {
  height: 100%;
  min-height: 0;
  min-width: 0;
  overflow: auto;
  overscroll-behavior: contain;
}
/* Width-only container. A SIZE container here (as this used to be) makes
   Chromium cancel every hover transition inside it the frame after it
   starts while the header orb redraws, so the drawings snapped to their
   hover pose instead of easing. The height tiers are attributes set by
   useShortCard (emptyArt.tsx): data-short ≤ 225px, data-shorter ≤ 140px,
   data-shortest ≤ 135px. */
.tri-empty-mark__frame {
  height: 100%;
  min-height: 0;
  container: empty-state / inline-size;
}
.tri-empty-mark__layout {
  display: grid;
  grid-template-rows: minmax(80px, 1fr) auto;
  gap: 10px;
  min-height: 100%;
  height: 100%;
  padding: 6px 12px 4px;
  text-align: center;
}
.tri-empty-mark__stage {
  display: grid;
  place-items: center;
  min-width: 0;
