.song-entry-primary, .song-entry-secondary { display: inline-flex; align-items: center; justify-content: center; gap: 10px; min-height: 36px; padding: 0 14px; border-radius: 5px; font-size: 12px; font-weight: 500; transition: background-color 150ms ease, color 150ms ease; }
