.song-editor-card { display: flex; flex-direction: column; gap: 10px; min-width: 0; padding: 12px 12px 8px; border: 1px solid rgb(229 243 242 / .12); border-radius: 6px; background: #1b1b1e; transition: border-color 150ms ease, background-color 150ms ease, opacity 150ms ease; }
