.song-editor-card-heading { display: flex; align-items: center; gap: 8px; min-width: 0; }
.song-editor-number { display: grid; place-items: center; flex-shrink: 0; width: 28px; height: 28px; border: 1px solid rgb(var(--tri-go-2) / .12); border-radius: 5px; background: rgb(var(--tri-go-2) / .06); color: rgb(var(--tri-go-2) / .85); font-size: 11px; font-variant-numeric: tabular-nums; }
