.song-editor-canvas textarea { display: block; width: 100%; resize: none; overflow: hidden; padding: 0 4px; border: 0; outline: none; background: transparent; color: var(--tri-ink); text-align: center; font-size: 15px; line-height: 1.65; }
.song-editor-canvas textarea::placeholder { color: rgb(229 243 242 / .32); font-size: 13px; }
.song-editor-card-tools { display: flex; align-items: center; justify-content: space-between; gap: 4px; }
