.song-editor-action:focus-visible, .song-editor-tool:focus-visible, .song-editor-title:focus-visible, .song-editor-author:focus-visible { outline: 2px solid rgb(var(--tri-go-2) / .7); outline-offset: 2px; }
.song-editor-action:active:not(:disabled), .song-editor-tool:active:not(:disabled) { background: rgb(var(--tri-go-2) / .15); }
@media (hover: hover) and (pointer: fine) {
