.song-close-scrim { position: absolute; inset: 0; z-index: 2; display: grid; place-items: center; padding: 20px; background: rgb(0 0 0 / .58); }
.song-close-card { width: min(100%, 390px); max-height: 100%; overflow-y: auto; display: flex; flex-direction: column; align-items: center; gap: 16px; padding: 28px; border-radius: 10px; background: var(--tri-pop); border: 1px solid rgb(255 255 255 / .14); box-shadow: 0 16px 50px rgb(0 0 0 / .3); text-align: center; animation: song-close-enter 180ms cubic-bezier(.23, 1, .32, 1); }
.song-close-card h2 { margin: 0; font-size: 20px; font-weight: 600; color: var(--tri-ink); }
.song-close-card p { margin: 0; font-size: 13px; line-height: 1.55; color: var(--tri-ink-muted); }
