/*
 * Motion for the songs tab that a class list cannot say.
 *
 * Everything here is opacity and transform only — no layout moves — and
 * every curve is the system's own ease-out, so a sweep of the pointer across
 * twenty cards is twenty cheap compositor animations and nothing else.
 */

/* ------------------------------------------------------------------ */
/* A song card's edit / delete pair                                    */
/* ------------------------------------------------------------------ */
/*
 * Hidden at rest, shown while the card is hovered or holds keyboard focus.
 *
 * In and out are different speeds on purpose. The rule that is NOT matched
 * sets the timing for the journey back to it, so the base rule carries the
 * slower exit (220ms) and the hover rule the quicker entrance (160ms). Sweep
 * across a row and each pair arrives promptly and lets go a beat late — a
 * wake behind the pointer rather than a row of switches.
 *
 * pointer-events follow visibility, so a pair on its way out can never eat a
 * click meant for the card, and nothing can be left stuck: there is no state
 * here at all, only :hover and :focus-within.
 */
.song-card-actions {
  opacity: 0;
  transform: translate3d(0, 3px, 0);
  pointer-events: none;
  will-change: opacity, transform;
  transition:
    opacity 220ms var(--tri-ease-out),
    transform 220ms var(--tri-ease-out);
}
.song-card:focus-within .song-card-actions {
  opacity: 1;
  transform: none;
  pointer-events: auto;
  transition-duration: 160ms;
}
@media (hover: hover) and (pointer: fine) {
  .song-card:hover .song-card-actions {
    opacity: 1;
    transform: none;
    pointer-events: auto;
    transition-duration: 160ms;
  }
}

/* ------------------------------------------------------------------ */
/* The tab dock                                                        */
/* ------------------------------------------------------------------ */
.tab-dock {
  animation: tab-dock-in 260ms var(--tri-ease-out) both;
}
@keyframes tab-dock-in {
  from {
    opacity: 0;
    transform: translate3d(0, 8px, 0);
  }
  to {
    opacity: 1;
    transform: translate3d(0, 0, 0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .song-card-actions {
    transition-duration: 1ms;
    transition-delay: 0s;
    transform: none;
  }
  .tab-dock {
    animation: none;
  }
}

/* Lyric sheets belong to the library; slide artwork belongs to the preview. */
.song-sheet { position: relative; display: flex; flex-direction: column; gap: 12px; width: 100%; min-height: 150px; padding: 16px 18px 26px; text-align: left; border-radius: 6px; border: 1px solid rgb(229 243 242 / .14); background: radial-gradient(ellipse at 0 0, rgb(var(--tri-teal-2) / .55), transparent 80%), #141818; }
