.stage-resizer-button { display: grid; place-items: center; width: 28px; height: 3px; border: 1px solid rgb(229 243 242 / .28); border-radius: 5px; background: rgb(229 243 242 / .035); pointer-events: none; transition: background-color 140ms ease, border-color 140ms ease; }
.stage-resizer-button > svg { display: none; }
