.verse-nav-hint::before { content: ''; position: absolute; inset: 0; background: radial-gradient(circle, rgb(255 255 255 / .28) 1px, transparent 1px) 0 0 / 7px 7px; mask-image: linear-gradient(to top, black, transparent 80%); }
