.verse-step--next:not(:disabled) { cursor: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='28' height='28' viewBox='0 0 28 28'><path d='M10.5 4 21 14 10.5 24V17.5H4v-7h6.5z' fill='white' stroke='rgb(0 0 0 / .7)' stroke-width='1.5' stroke-linejoin='round'/></svg>") 14 14, e-resize; }

