/* A song is one card with a fixed reading area and an always-available pager. */
.song-library-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(218px, 1fr)); align-items: stretch; gap: 12px; padding: 2px var(--tri-card-gap) 12px; }
.song-library-grid .song-card { --song-tint: 91 151 135; min-width: 0; overflow: hidden; border: 1px solid rgb(var(--song-tint) / .25); border-radius: 12px; background: linear-gradient(145deg, rgb(var(--song-tint) / .13), transparent 72%), #151918; }
.song-library-grid .song-card[data-tone='1'] { --song-tint: 129 146 183; }
.song-library-grid .song-card[data-tone='2'] { --song-tint: 175 139 171; }
.song-library-grid .song-card[data-tone='3'] { --song-tint: 179 155 105; }
.song-library-grid .song-card[data-live='true'] { border-color: rgb(var(--tri-go-2)); box-shadow: inset 0 0 0 1px rgb(var(--tri-go-2) / .35); }
.song-library-grid[data-has-live='true'] .song-card:not([data-live='true']) { --song-tint: 148 156 155; background: #171a19; border-color: rgb(229 243 242 / .12); }
.song-card-open { display: flex; flex-direction: column; align-items: stretch; width: 100%; padding: 14px 16px 12px; text-align: left; }
.song-card-open:focus-visible { outline: 2px solid var(--tri-accent-yellow); outline-offset: -3px; border-radius: 10px; }
.song-card-topline { display: flex; align-items: center; gap: 7px; color: rgb(var(--song-tint) / 1); font-size: 10px; line-height: 16px; }
.song-card-topline > span { flex: 1; }
.song-card-title { overflow: hidden; margin-top: 12px; color: #e5f3f2; font-size: 14px; font-weight: 600; line-height: 19px; white-space: nowrap; text-overflow: ellipsis; }
.song-card-artist { overflow: hidden; height: 17px; margin-top: 2px; color: rgb(229 243 242 / .46); font-size: 11px; line-height: 17px; white-space: nowrap; text-overflow: ellipsis; }
.song-card-excerpt { display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 4; height: 72px; overflow: hidden; margin-top: 15px; color: rgb(229 243 242 / .82); font-size: 12px; line-height: 18px; }
.song-card-excerpt > span { display: block; }
.song-card-footer { display: flex; flex-direction: column; gap: 8px; padding: 8px 12px 10px 16px; border-top: 1px solid rgb(var(--song-tint) / .13); background: rgb(0 0 0 / .12); }
.song-card-navigation, .song-card-command-row { display: flex; align-items: center; justify-content: space-between; gap: 8px; width: 100%; }
.song-card-go-live.tri-label { --tri-control-h: 28px; padding-inline: 10px; font-size: 11px; }
.song-card-section { flex: 1; min-width: 0; overflow: hidden; color: rgb(229 243 242 / .56); font-size: 10px; line-height: 14px; white-space: nowrap; text-overflow: ellipsis; }
.song-card-section small { display: block; color: rgb(229 243 242 / .35); font-size: 9px; font-variant-numeric: tabular-nums; }
.song-card-footer .song-card-actions, .song-card-pager { display: flex; flex: 0 0 auto; align-items: center; gap: 2px; }
.song-card-actions button, .song-card-pager button { display: grid; place-items: center; width: 26px; height: 28px; border-radius: 5px; color: rgb(229 243 242 / .65); }
.song-card-pager button { background: rgb(var(--song-tint) / .12); }
.song-card-actions button:hover, .song-card-pager button:hover { color: #e5f3f2; background: rgb(var(--song-tint) / .22); }
.song-card-footer button:disabled { opacity: .25; cursor: default; }
.song-card-footer button:focus-visible { outline: 2px solid var(--tri-accent-yellow); outline-offset: 1px; }
.song-card-footer .song-card-delete:hover { color: #f2b2aa; background: rgb(162 66 55 / .2); }
.song-library-search { display: flex; min-width: 0; width: 100%; }
.song-search-modes { display: flex; align-self: stretch; flex: 0 0 auto; gap: 2px; padding: 3px; border: 1px solid rgb(229 243 242 / .12); border-radius: 8px; }
.song-search-modes button { padding: 0 12px; border-radius: 5px; color: rgb(229 243 242 / .48); font-size: 12px; }
.song-search-modes button[aria-pressed='true'] { color: #e5f3f2; background: rgb(229 243 242 / .1); }
.song-search-modes button:focus-visible { outline: 1px solid var(--tri-accent-yellow); outline-offset: 1px; }
.song-match-note { display: flex; justify-content: space-between; gap: 10px; padding: 0 16px 10px; color: rgb(229 243 242 / .5); font-size: 11px; }
.song-match-note button { color: rgb(229 243 242 / .85); }
.song-detail-header { display: flex; align-items: center; gap: 12px; width: 100%; min-width: 0; padding: 0; }
.song-detail-back { display: flex; flex: 0 0 auto; align-items: center; gap: 5px; height: var(--tri-field-h); padding: 0 10px 0 7px; border: 1px solid rgb(229 243 242 / .14); border-radius: 7px; color: rgb(229 243 242 / .75); font-size: 12px; }
.song-detail-back:hover { background: rgb(229 243 242 / .06); color: #e5f3f2; }
.song-detail-back:focus-visible { outline: 2px solid var(--tri-accent-yellow); outline-offset: 2px; }
.song-detail-title { display: flex; flex: 1; flex-direction: column; justify-content: center; gap: 1px; min-width: 0; height: var(--tri-field-h); }
.song-detail-title > strong { overflow: hidden; color: #e5f3f2; font-size: 14px; line-height: 16px; white-space: nowrap; text-overflow: ellipsis; }
.song-detail-title > span { overflow: hidden; color: rgb(229 243 242 / .45); font-size: 11px; line-height: 12px; white-space: nowrap; text-overflow: ellipsis; }
.song-detail-search { flex: 0 0 30%; width: 30%; min-width: 0; }
.song-detail-content { padding: 2px var(--tri-card-gap) 12px; }
.song-send-problem { padding: 0 var(--tri-card-gap) 8px; color: #efb0a6; font-size: 12px; }
.song-lyrics-empty { display: grid; justify-items: center; gap: 12px; padding: 30px 16px; color: rgb(229 243 242 / .6); font-size: 13px; }
@media (hover: none) { .song-card-footer .song-card-actions { opacity: 1; transform: none; pointer-events: auto; } }
@media (max-width: 760px) { .song-detail-header { flex-wrap: wrap; gap: 8px; } .song-detail-search { flex: 1 0 100%; width: 100%; } }

.stock-search { container: stock-search / size; }
.stock-kind-picker {
  align-self: flex-end;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 4px;
  height: var(--tri-field-h);
  padding: 4px;
  border: 1px solid rgb(255 255 255 / .1);
  background: rgb(27 30 30 / .94);
}
.media-browser > .stock-kind-picker {
  position: absolute;
  top: calc(var(--tri-field-h) + 0.75rem);
  right: var(--tri-card-gap);
  z-index: 20;
  box-shadow: 0 4px 16px rgb(0 0 0 / .25);
}
.media-browser__notice { padding-right: 150px; }
.stock-kind-picker button {
  display: grid;
  place-items: center;
  padding: 0 12px;
  font-size: var(--tri-size-xs);
  height: calc(var(--tri-field-h) - 10px);
  border-radius: 6px;
  color: rgb(229 243 242 / .6);
  transition: background-color 150ms ease, color 150ms ease;
}
.stock-kind-picker button:hover { background: rgb(255 255 255 / .1); color: var(--tri-ink); }
.stock-kind-picker button[aria-pressed="true"] { background: rgb(255 255 255 / .15); color: var(--tri-ink); }
.stock-kind-picker button:focus-visible { outline: 2px solid var(--tri-accent-yellow); outline-offset: 2px; }
@media (prefers-reduced-motion: reduce) { .stock-kind-picker button { transition: none; } }
.stock-search__presets { overflow-x: auto; padding-bottom: 3px; }
.stock-search__presets > button { flex-shrink: 0; }
@container stock-search (max-height: 330px) {
  .stock-search__toolbar { gap: 6px; }
  .stock-search__presets { gap: 4px; }
  .stock-search__presets > button { height: 24px; }
}

.media-picture-grid { grid-template-columns: repeat(auto-fill, minmax(min(150px, 100%), 1fr)); }
.stock-results-grid { grid-template-columns: repeat(7, minmax(0, 1fr)); }
.stock-picture-card { border: 1px solid rgb(229 243 242 / .12); }
.stock-picture-card:hover { border-color: rgb(229 243 242 / .3); }
.stock-picture-card:focus-visible { outline: 2px solid var(--tri-accent-yellow); outline-offset: 2px; }
@container stock-search (max-width: 1100px) { .stock-results-grid { grid-template-columns: repeat(6, minmax(0, 1fr)); } }
@container stock-search (max-width: 850px) { .stock-results-grid { grid-template-columns: repeat(5, minmax(0, 1fr)); } }
@container stock-search (max-width: 650px) { .stock-results-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); } }
@container stock-search (max-width: 480px) { .stock-results-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
@container stock-search (max-width: 320px) { .stock-results-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.media-carousel { container: media-carousel / inline-size; }
.media-carousel__rail { display: flex; overflow: auto; scroll-snap-type: x mandatory; overscroll-behavior-x: contain; }
.media-carousel__page { flex: 0 0 100%; min-width: 0; scroll-snap-align: start; padding: 1px 4px var(--tri-gap); }
.media-carousel__bento { columns: 3; column-gap: 8px; }
.media-carousel__bento > * { break-inside: avoid; margin-bottom: 8px; }
@container media-carousel (max-width: 540px) { .media-carousel__bento { columns: 2; } }
@container media-carousel (max-width: 300px) { .media-carousel__bento { columns: 1; } }
.media-picture-caption { position: absolute; inset: auto 0 0; padding: 24px 10px 10px; background: linear-gradient(transparent, rgb(0 0 0 / .85)); opacity: 0; pointer-events: none; transition: opacity 150ms ease; }
.media-picture-card:hover .media-picture-caption,
.media-picture-card:focus-visible .media-picture-caption { opacity: 1; }
@media (hover: none) { .media-picture-caption { opacity: 1; } }
@media (prefers-reduced-motion: reduce) { .media-picture-caption { transition: none; } }

/* Compact controls share the bento cards' dark material; the orb stays bare. */
.tri-live-header {
  --tri-view-inset: 2px;
  --tri-header-tray-h: calc(var(--tri-field-h) + var(--tri-view-inset) * 2);
  gap: var(--tri-gap);
  padding: 0;
  border: 0;
  background: transparent;
}

.tri-live-header .tri-header-control {
  --tri-header-bg: #111111;
  --header-stroke: rgb(229 243 242 / var(--tri-stroke-opacity));
  height: var(--tri-header-tray-h);
  padding: 0 calc(var(--tri-control-pad-x) * .75);
  gap: 6px;
  border: 0;
  border-radius: var(--tri-radius-control);
  corner-shape: var(--tri-corner);
  background-color: var(--tri-header-bg);
  background-image: none;
  box-shadow: inset 0 0 0 var(--tri-border) var(--header-stroke);
  color: var(--tri-ink);
  font-family: var(--tri-font);
  font-size: var(--tri-size);
  font-weight: var(--tri-weight);
  letter-spacing: var(--tri-tracking);
  line-height: 1;
  text-shadow: var(--tri-text-shadow);
  white-space: nowrap;
  transition:
    background-color var(--tri-dur-state) var(--tri-ease-out),
    box-shadow var(--tri-dur-state) var(--tri-ease-out),
    color var(--tri-dur-state) var(--tri-ease-out),
    transform var(--tri-dur-press) var(--tri-ease-out);
}
/* Every control leads with its glyph, a touch quieter than its word. */
.tri-live-header .tri-header-icon { flex: none; opacity: 0.82; }

.tri-live-header button.tri-header-control { cursor: pointer; }
@media (hover: hover) and (pointer: fine) {
  .tri-live-header button.tri-header-control:hover:not(:disabled),
  .tri-live-header label.tri-header-control:hover {
    --tri-header-bg: #1e1e1e;
    --header-stroke: rgb(229 243 242 / var(--tri-stroke-opacity-hover));
  }
}
.tri-live-header button.tri-header-control:active:not(:disabled) {
  transform: scale(var(--tri-press-scale));
}
.tri-live-header button.tri-header-control:focus-visible {
  outline: 2px solid var(--tri-accent-yellow);
  outline-offset: 2px;
}
.tri-live-header .tri-header-control[aria-pressed='true'],
.tri-live-header .tri-header-control[aria-expanded='true'] {
  --tri-header-bg: #222222;
}
.tri-live-header button.tri-header-control:disabled {
  cursor: not-allowed;
  opacity: 0.4;
}

/* The tray fills the sidebar column; compact gaps stay fixed as buttons grow. */
.tri-header-views {
  --tri-view-w: calc(var(--tri-control-h) * 1.125);
  flex: 1 1 0;
  width: 100%;
  max-width: 100%;
  position: relative;
  isolation: isolate;
  height: var(--tri-header-tray-h);
  padding: var(--tri-view-inset);
  justify-content: flex-start;
  gap: 2px;
  border-radius: calc(var(--tri-radius-control) + var(--tri-view-inset));
  corner-shape: var(--tri-corner);
  background: #111111;
  box-shadow: inset 0 0 0 var(--tri-border) rgb(255 255 255 / 0.055);
}

/* Sliding motion adapted from LeonLinBuild's nav:
   https://codepen.io/LeonLinBuild/pen/emdgRJj */
.tri-header-view-pill {
  position: absolute;
  inset: var(--tri-view-inset) auto var(--tri-view-inset) 0;
  z-index: 0;
  width: var(--tri-view-pill-w, var(--tri-view-w));
  border-radius: 5px;
  corner-shape: round;
  background: #333333;
  pointer-events: none;
  transform: translateX(var(--tri-view-pill-x, 0px));
}
.tri-header-views[data-pill-sliding='true'] .tri-header-view-pill {
  transition: transform 500ms cubic-bezier(0.34, 1.2, 0.64, 1);
}
.tri-live-header .tri-header-views .tri-header-view {
  --header-bg: transparent;
  --header-hover: transparent;
  --header-active: transparent;
  --header-edge: transparent;
  --header-accent: #777777;
  --header-ink: #aaaaaa;
  position: relative;
  z-index: 1;
  background-color: transparent;
  background-image: none;
  box-shadow: none;
  text-shadow: none;
  width: auto;
  height: var(--tri-field-h);
  min-width: var(--tri-view-w);
  flex-grow: 1;
  flex-shrink: 1;
  padding: 0;
  gap: 0;
  border: 0;
  border-radius: 5px;
  corner-shape: round;
  transition: color 300ms ease;
}
/* One bubble travels between icons; the selected pill only follows clicks. */
.tri-header-view-hint {
  position: absolute;
  z-index: 3;
  left: 0;
  bottom: calc(50% + var(--tri-control-h) * 0.28125 + 2px);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translateX(var(--tri-view-hint-x, 0px));
  transition: opacity var(--tri-view-hint-fade) ease, visibility 0s linear var(--tri-view-hint-fade);
}
.tri-header-view-hint[data-moving='true'] {
  transition:
    transform 220ms cubic-bezier(0.22, 1, 0.36, 1),
    opacity var(--tri-view-hint-fade) ease,
    visibility 0s linear var(--tri-view-hint-fade);
}
.tri-header-view-hint[data-open='true'] {
  opacity: 1;
  visibility: visible;
  transition-delay: 0s;
}
.tri-header-view-hint-bubble {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  width: var(--tri-view-hint-w, 0px);
  padding: 2px 6px;
  border: 1px solid #383838;
  border-radius: 4px;
  corner-shape: round;
  background: #202020;
  color: #f5f5f5;
  font-size: var(--tri-control-size);
  font-weight: 500;
  letter-spacing: 0.015em;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  transform: translateX(-50%);
}
.tri-header-view-hint[data-moving='true'] .tri-header-view-hint-bubble {
  transition: width 180ms cubic-bezier(0.22, 1, 0.36, 1);
}
.tri-header-view-hint-name,
.tri-header-view-hint-old {
  grid-area: 1 / 1;
  justify-self: center;
  width: max-content;
}
.tri-header-view-hint[data-moving='true'] .tri-header-view-hint-name {
  animation: tri-view-hint-in 120ms ease both;
}
.tri-header-view-hint-old {
  animation: tri-view-hint-out 120ms ease both;
}
@keyframes tri-view-hint-in {
  from { opacity: 0; transform: translateX(var(--tri-view-hint-shift)); }
  to { opacity: 1; transform: translateX(0); }
}
@keyframes tri-view-hint-out {
  from { opacity: 1; transform: translateX(0); }
  to { opacity: 0; transform: translateX(calc(-1 * var(--tri-view-hint-shift))); }
}
.tri-live-header .tri-header-views .tri-header-view[aria-pressed='true'] {
  background: transparent;
  border-color: transparent;
  color: #f5f5f5;
}
.tri-live-header .tri-header-views .tri-header-view:is(:hover, :focus-visible, [data-hint-target='true']):not(:disabled) {
  background: #282828;
  border-color: transparent;
  color: #f5f5f5;
}
.tri-live-header .tri-header-views .tri-header-view[aria-pressed='true']:is(:hover, :focus-visible) {
  background: #333333;
}
.tri-header-view-symbol {
  display: flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: var(--tri-view-w);
  height: 100%;
}
.tri-header-view-label {
  display: block;
  min-width: 0;
  flex-shrink: 1;
  width: 0;
  overflow: hidden;
  opacity: 0;
  transform: translateX(8px);
  pointer-events: none;
  transition:
    width 240ms cubic-bezier(0.32, 0.72, 0, 1),
    opacity 160ms ease,
    transform 240ms cubic-bezier(0.32, 0.72, 0, 1);
}
.tri-header-view-label > span {
  display: block;
  width: max-content;
  padding-right: calc(var(--tri-control-pad-x) * .75);
  white-space: nowrap;
}
/* The name opens inside the pill only after selecting the tab. */
.tri-header-view[aria-pressed='true'] .tri-header-view-label {
  width: var(--tri-view-label-w, 16ch);
  opacity: 1;
  transform: translateX(0);
}

.tri-header-view-icon {
  width: calc(var(--tri-control-h) * 0.6875);
  height: calc(var(--tri-control-h) * 0.6875);
  transition: transform 200ms cubic-bezier(0.32, 0.72, 0, 1);
}
.tri-header-view:active .tri-header-view-icon {
  transform: scale(0.92);
}

/* The orb is not a control. It is the engine's face: bare on the ground,
   no box of its own, and a size up from the buttons beside it. */
/* Taller than the strip on purpose: it overhangs the row a few px each way. */
.tri-live-header .tri-header-orb { margin-left: 0; height: var(--tri-topbar-h); }
.tri-header-orb-face { border-radius: 50%; padding: 0; background: none; cursor: pointer; }
.tri-header-orb-face:focus-visible { outline: 2px solid var(--tri-accent-yellow); outline-offset: 2px; }

/* Tones: four stops each, nothing else changes — see tokens.css. */
.tri-live-header .tri-header-listen { font-weight: 600; }
.tri-live-header .tri-header-listen[aria-pressed='true'] {
  --header-stroke: rgb(var(--tri-go-2) / 0.5);
}
.tri-live-header .tri-header-listen[data-error='true'] {
  --tri-1: var(--tri-red-1);
  --tri-2: var(--tri-red-2);
  --tri-3: var(--tri-red-3);
  --tri-4: var(--tri-red-4);
  color: var(--tri-ink-danger);
}
/* The pickers are neutral: they say nothing about the service. */
.tri-live-header .tri-header-audio,
.tri-live-header .tri-header-remote,
.tri-live-header .tri-header-import {
  --tri-1: var(--tri-ash-1);
  --tri-2: var(--tri-ash-2);
  --tri-3: var(--tri-ash-3);
  --tri-4: var(--tri-ash-4);
}
.tri-live-header .tri-header-clock {
  --tri-1: var(--tri-indigo-1);
  --tri-2: var(--tri-indigo-2);
  --tri-3: var(--tri-indigo-3);
  --tri-4: var(--tri-indigo-4);
}
.tri-header-log-slot { width: var(--tri-rail-w); flex-shrink: 1; }
.tri-header-status-dot { background: rgb(var(--tri-go-2)); }
.tri-live-header .tri-header-log[data-attention='true'] {
  --tri-1: var(--tri-gold-1);
  --tri-2: var(--tri-gold-2);
  --tri-3: var(--tri-gold-3);
  --tri-4: var(--tri-gold-4);
}
.tri-header-log[data-attention='true'] .tri-header-status-dot { background: var(--tri-accent-yellow); }

@media (prefers-reduced-motion: reduce) {
  .tri-live-header .tri-header-control,
  .tri-live-header .tri-header-views .tri-header-view,
  .tri-live-header .tri-header-views .tri-header-view-pill,
  .tri-live-header .tri-header-views .tri-header-view-hint,
  .tri-live-header .tri-header-views .tri-header-view-hint-bubble,
  .tri-header-view-label,
  .tri-header-view-icon { transition: none; }
  .tri-header-view-hint-name,
  .tri-header-view-hint-old { animation: none !important; }
  .tri-header-view-hint-old { display: none; }
}

/* The audio picker is a control holding a native select: the select draws
   nothing of its own, the control draws the box. */
.tri-live-header .tri-header-audio select { font: inherit; letter-spacing: inherit; }
.tri-live-header .tri-header-audio select option { color: #0b1214; }
/* Workspace navigation responds immediately; no half-second label/pill travel. */
.tri-header-views .tri-header-view-pill,
.tri-header-views[data-pill-sliding='true'] .tri-header-view-pill,
.tri-header-views .tri-header-view-label,
.tri-header-views .tri-header-view-symbol { transition: none; }

/* Preview controls sit below their canvas; live controls sit above it. */
.stage-toolbar-actions > button { min-height: var(--tri-field-h); }
.stage-live-label { display: inline-flex; align-items: center; gap: 8px; height: var(--tri-field-h); padding-inline: 9px; color: var(--tri-ink-muted); font-size: var(--tri-control-size); font-weight: 500; line-height: 1; }
.stage-live-signal { display: grid; place-items: center; width: 16px; height: 16px; border: 1px solid rgb(229 243 242 / .16); border-radius: 50%; }
.stage-live-signal > span { width: 6px; height: 6px; border-radius: 50%; background: rgb(229 243 242 / .35); }
.stage-live-label[data-active] { color: var(--tri-ink); }
.stage-live-label[data-active] .stage-live-signal { border-color: rgb(231 107 98 / .35); }
.stage-live-label[data-active] .stage-live-signal > span { background: #e76b62; animation: stage-on-air 2.4s ease-in-out infinite; }
@keyframes stage-on-air { 0%, 100% { opacity: 1; } 50% { opacity: .45; } }
@media (prefers-reduced-motion: reduce) {
  .stage-live-label[data-active] .stage-live-signal > span { animation: none; }
}

/* Both splitters expose the same arrow without enlarging the gutter. */
